-- MTH 121 (Elementary Mathematics II, UNN) practice questions for the CBT feature.
-- 292 questions grounded in the official UNN Mathematics department textbook
-- ("Introductory University Mathematics 2: Calculus", Amazigo et al.) and the
-- official UNN MTH121 course outline, plus additional real calculus questions
-- (all staying within the outline's 6 topics: functions/limits/continuity, the
-- derivative as rate of change, techniques of differentiation, curve sketching
-- and integration as the inverse of differentiation, methods of integration,
-- and applications of integration to areas/volumes). Every answer is
-- sympy-verified and every explanation is a genuine step-by-step derivation.
--
-- Rendering convention (revised): LaTeX is used ONLY for genuine mathematical
-- notation ($...$-delimited inline math); ordinary prose is left as plain
-- text, not force-wrapped word-by-word. This is simpler and more robust than
-- the earlier "every word in LaTeX" convention, which had repeatedly caused
-- real rendering bugs (glued-together words, wrong italic font, oversized
-- text) because prose was being routed through the math renderer for no
-- benefit. MathText already natively supports this mixed plain-text/LaTeX
-- style; see lib/core/widgets/math_text.dart.
--
-- cbt_questions has no course_code column, so the MTH 121 link lives in
-- subject_name. is_general = false and faculty is pinned to 'Faculty of
-- Physical Sciences' so only students in that faculty see this paper.

delete from public.cbt_questions where subject_id = 'mth-121-calculus';

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general)
values
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = 2x-3$, $g(x) = x^2+1$, find $(f \circ g)(2)$.', '["$5$", "$7$", "$6$", "$2$"]'::jsonb, 1, '$(f \circ g)(2) = f(g(2))$. First find $g(2)$ by substituting $x=2$ into $g(x) = x^{2} + 1$: $g(2) = 2^{2} + 1 = 5$. Then substitute $g(2) = 5$ into $f(x) = 2 x - 3$: $f(5) = 2 \cdot 5 - 3 = 7$. So $(f \circ g)(2) = 7$.', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = x^2$, $g(x) = 3x-1$, find $(f \circ g)(1)$.', '["$5$", "$2$", "$4$", "$3$"]'::jsonb, 2, '$(f \circ g)(1) = f(g(1))$. First find $g(1)$ by substituting $x=1$ into $g(x) = 3 x - 1$: $g(1) = 3 \cdot 1 - 1 = 2$. Then substitute $g(1) = 2$ into $f(x) = x^{2}$: $f(2) = 2^{2} = 4$. So $(f \circ g)(1) = 4$.', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = |x|$, $g(x) = 2x-5$, find $(f \circ g)(1)$.', '["$3$", "$-2$", "$-3$", "$4$"]'::jsonb, 0, '$(f \circ g)(1) = f(g(1))$. First find $g(1)$ by substituting $x=1$ into $g(x) = 2 x - 5$: $g(1) = 2 \cdot 1 - 5 = -3$. Then substitute $g(1) = -3$ into $f(x) = \left|{x}\right|$: $f(-3) = \left|{-3}\right| = 3$. So $(f \circ g)(1) = 3$.', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = 3x+4$, $g(x) = x^2-2x$, find $(f \circ g)(3)$.', '["$16$", "$3$", "$13$", "$143$"]'::jsonb, 2, '$(f \circ g)(3) = f(g(3))$. First find $g(3)$ by substituting $x=3$ into $g(x) = x^{2} - 2 x$: $g(3) = 3^{2} - 2 \cdot 3 = 3$. Then substitute $g(3) = 3$ into $f(x) = 3 x + 4$: $f(3) = 3 \cdot 3 + 4 = 13$. So $(f \circ g)(3) = 13$.', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = x^2-1$, $g(x) = x+2$, find $(f \circ g)(-1)$.', '["$-1$", "$1$", "$2$", "$0$"]'::jsonb, 3, '$(f \circ g)(-1) = f(g(-1))$. First find $g(-1)$ by substituting $x=-1$ into $g(x) = x + 2$: $g(-1) = -1 + 2 = 1$. Then substitute $g(-1) = 1$ into $f(x) = x^{2} - 1$: $f(1) = 1^{2} - 1 = 0$. So $(f \circ g)(-1) = 0$.', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = 5-x$, $g(x) = x^2$, find $(f \circ g)(3)$.', '["$9$", "$4$", "$11$", "$-4$"]'::jsonb, 3, '$(f \circ g)(3) = f(g(3))$. First find $g(3)$ by substituting $x=3$ into $g(x) = x^{2}$: $g(3) = 3^{2} = 9$. Then substitute $g(3) = 9$ into $f(x) = 5 - x$: $f(9) = 5 - 9 = -4$. So $(f \circ g)(3) = -4$.', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = x^3$, $g(x) = x-1$, find $(f \circ g)(2)$.', '["$7$", "$1$", "$2$", "$9$"]'::jsonb, 1, '$(f \circ g)(2) = f(g(2))$. First find $g(2)$ by substituting $x=2$ into $g(x) = x - 1$: $g(2) = 2 - 1 = 1$. Then substitute $g(2) = 1$ into $f(x) = x^{3}$: $f(1) = 1^{3} = 1$. So $(f \circ g)(2) = 1$.', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = 4-2x$, $g(x) = x^2+3$, find $(f \circ g)(1)$.', '["$6$", "$4$", "$7$", "$-4$"]'::jsonb, 3, '$(f \circ g)(1) = f(g(1))$. First find $g(1)$ by substituting $x=1$ into $g(x) = x^{2} + 3$: $g(1) = 1^{2} + 3 = 4$. Then substitute $g(1) = 4$ into $f(x) = 4 - 2 x$: $f(4) = 4 - 2 \cdot 4 = -4$. So $(f \circ g)(1) = -4$.', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = 2x+1$, $g(x) = x^2$, find $(f+g)(3)$.', '["$-2$", "$63$", "$7$", "$16$"]'::jsonb, 3, '$(f+g)(3) = f(3) + g(3)$. Substituting $x=3$: $f(3) = 2 \cdot 3 + 1 = 7$ and $g(3) = 3^{2} = 9$, so $(f+g)(3) = 7 + 9 = 16$.', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = 2x+1$, $g(x) = x^2$, find $(f \cdot g)(3)$.', '["$16$", "$63$", "$-2$", "$9$"]'::jsonb, 1, '$(f \cdot g)(3) = f(3) \cdot g(3)$. Substituting $x=3$: $f(3) = 2 \cdot 3 + 1 = 7$ and $g(3) = 3^{2} = 9$, so $(f \cdot g)(3) = 7 \cdot 9 = 63$.', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = x^2-4$, $g(x) = x+2$, find $(f+g)(1)$.', '["$-6$", "$0$", "$-9$", "$-3$"]'::jsonb, 1, '$(f+g)(1) = f(1) + g(1)$. Substituting $x=1$: $f(1) = 1^{2} - 4 = -3$ and $g(1) = 1 + 2 = 3$, so $(f+g)(1) = -3 + 3 = 0$.', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = x^2-4$, $g(x) = x+2$, find $(f \cdot g)(1)$.', '["$-9$", "$-6$", "$3$", "$0$"]'::jsonb, 0, '$(f \cdot g)(1) = f(1) \cdot g(1)$. Substituting $x=1$: $f(1) = 1^{2} - 4 = -3$ and $g(1) = 1 + 2 = 3$, so $(f \cdot g)(1) = -3 \cdot 3 = -9$.', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = 3x$, $g(x) = x-5$, find $(f+g)(4)$.', '["$-12$", "$11$", "$12$", "$13$"]'::jsonb, 1, '$(f+g)(4) = f(4) + g(4)$. Substituting $x=4$: $f(4) = 3 \cdot 4 = 12$ and $g(4) = 4 - 5 = -1$, so $(f+g)(4) = 12 + -1 = 11$.', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = 3x$, $g(x) = x-5$, find $(f \cdot g)(4)$.', '["$-12$", "$13$", "$-1$", "$11$"]'::jsonb, 0, '$(f \cdot g)(4) = f(4) \cdot g(4)$. Substituting $x=4$: $f(4) = 3 \cdot 4 = 12$ and $g(4) = 4 - 5 = -1$, so $(f \cdot g)(4) = 12 \cdot -1 = -12$.', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = x^2+2$, $g(x) = 2x-1$, find $(f+g)(2)$.', '["$18$", "$6$", "$3$", "$9$"]'::jsonb, 3, '$(f+g)(2) = f(2) + g(2)$. Substituting $x=2$: $f(2) = 2^{2} + 2 = 6$ and $g(2) = 2 \cdot 2 - 1 = 3$, so $(f+g)(2) = 6 + 3 = 9$.', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = x^2+2$, $g(x) = 2x-1$, find $(f \cdot g)(2)$.', '["$18$", "$19$", "$3$", "$9$"]'::jsonb, 0, '$(f \cdot g)(2) = f(2) \cdot g(2)$. Substituting $x=2$: $f(2) = 2^{2} + 2 = 6$ and $g(2) = 2 \cdot 2 - 1 = 3$, so $(f \cdot g)(2) = 6 \cdot 3 = 18$.', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = 3x-4$, find $f^{-1}(5)$.', '["$27$", "$1/3$", "$11$", "$3$"]'::jsonb, 3, 'To find $f^{-1}(5)$, solve $f(x) = 5$ for $x$: $3 x - 4 = 5$. Rearranging gives $x = 3$, so $f^{-1}(5) = 3$.', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = 2x+7$, find $f^{-1}(3)$.', '["$5$", "$-2$", "$13$", "$-8$"]'::jsonb, 1, 'To find $f^{-1}(3)$, solve $f(x) = 3$ for $x$: $2 x + 7 = 3$. Rearranging gives $x = -2$, so $f^{-1}(3) = -2$.', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = -x+6$, find $f^{-1}(2)$.', '["$4$", "$3$", "$-8$", "$5$"]'::jsonb, 0, 'To find $f^{-1}(2)$, solve $f(x) = 2$ for $x$: $6 - x = 2$. Rearranging gives $x = 4$, so $f^{-1}(2) = 4$.', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = 5x+1$, find $f^{-1}(11)$.', '["$12/5$", "$2$", "$56$", "$50$"]'::jsonb, 1, 'To find $f^{-1}(11)$, solve $f(x) = 11$ for $x$: $5 x + 1 = 11$. Rearranging gives $x = 2$, so $f^{-1}(11) = 2$.', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = 4x-3$, find $f^{-1}(9)$.', '["$33$", "$3/2$", "$3$", "$48$"]'::jsonb, 2, 'To find $f^{-1}(9)$, solve $f(x) = 9$ for $x$: $4 x - 3 = 9$. Rearranging gives $x = 3$, so $f^{-1}(9) = 3$.', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'What is the domain of $f(x) = 1/(x-3)?$', '["R", "R except x = 3", "$x > 3$ only", "$x < 3$ only"]'::jsonb, 1, 'For $f(x) = \frac{1}{x - 3}$ to be defined, the denominator must not be zero: $x - 3 \neq 0$, which excludes $x = 3$. Combining these conditions, the domain is $\left(-\infty, 3\right) \cup \left(3, \infty\right)$.', 'Real-valued Functions of a Real Variable', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'What is the domain of $f(x) = \sqrt{x-2}?$', '["$x \\geq 2$", "$x > 2$", "all real x", "$x \\leq 2$"]'::jsonb, 0, 'For $f(x) = \sqrt{x - 2}$ to be defined, the expression under the square root must be non-negative: $x - 2 \geq 0$, which gives $\left[2, \infty\right)$. Combining these conditions, the domain is $\left[2, \infty\right)$.', 'Real-valued Functions of a Real Variable', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'What is the domain of $f(x) = 1/\sqrt{x+5}?$', '["$x < -5$", "all real x", "$x \\geq -5$", "$x > -5$"]'::jsonb, 3, 'For $f(x) = \frac{1}{\sqrt{x + 5}}$ to be defined, the denominator must not be zero: $\sqrt{x + 5} \neq 0$, which excludes $x = -5$. Combining these conditions, the domain is $\left(-5, \infty\right)$.', 'Real-valued Functions of a Real Variable', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'What is the domain of $f(x) = \sqrt{9-x^2}?$', '["$-3 \\leq x \\leq 3$", "all real x", "$x \\leq -3$", "$x \\geq 3$"]'::jsonb, 0, 'For $f(x) = \sqrt{9 - x^{2}}$ to be defined, the expression under the square root must be non-negative: $9 - x^{2} \geq 0$, which gives $\left[-3, 3\right]$. Combining these conditions, the domain is $\left[-3, 3\right]$.', 'Real-valued Functions of a Real Variable', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'What is the domain of $f(x) = 1/(x^2-4)?$', '["all real x", "R except x = 2 and x = -2", "R except x = 2", "R except x = -2"]'::jsonb, 1, 'For $f(x) = \frac{1}{x^{2} - 4}$ to be defined, the denominator must not be zero: $x^{2} - 4 \neq 0$, which excludes $x = -2 \textrm{ and } x = 2$. Combining these conditions, the domain is $\left(-\infty, -2\right) \cup \left(-2, 2\right) \cup \left(2, \infty\right)$.', 'Real-valued Functions of a Real Variable', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'What is the domain of $f(x) = \sqrt{x+1}/(x-4)?$', '["$x \\geq -1$", "$x > -1$", "$x \\geq -1, x \\neq 4$", "all real x"]'::jsonb, 2, 'For $f(x) = \frac{\sqrt{x + 1}}{x - 4}$ to be defined, the denominator must not be zero: $x - 4 \neq 0$, which excludes $x = 4$; and the expression under the square root must be non-negative: $x + 1 \geq 0$, which gives $\left[-1, \infty\right)$. Combining these conditions, the domain is $\left[-1, 4\right) \cup \left(4, \infty\right)$.', 'Real-valued Functions of a Real Variable', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 2} [3x^2 - 5x + 7]$.', '["$10$", "$-9$", "$7$", "$9$"]'::jsonb, 3, 'Since $f(x) = 3 x^{2} - 5 x + 7$ is continuous at $x=2$ (the denominator, if any, is not zero there), substitute directly: $\lim_{x \to 2} 3 x^{2} - 5 x + 7 = 3 \cdot 2^{2} - 5 \cdot 2 + 7 = 9$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to -1} [x^3 - 4x + 1]$.', '["$-1$", "$5$", "$4$", "$-4$"]'::jsonb, 2, 'Since $f(x) = x^{3} - 4 x + 1$ is continuous at $x=-1$ (the denominator, if any, is not zero there), substitute directly: $\lim_{x \to -1} x^{3} - 4 x + 1 = \left(-1\right)^{3} - 4 \left(-1\right) + 1 = 4$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 4} [(2x + 3)/(x - 1)]$.', '["$14/3$", "$11/3$", "$-5/9$", "$-11/3$"]'::jsonb, 1, 'Since $f(x) = \frac{2 x + 3}{x - 1}$ is continuous at $x=4$ (the denominator, if any, is not zero there), substitute directly: $\lim_{x \to 4} \frac{2 x + 3}{x - 1} = \frac{2 \cdot 4 + 3}{4 - 1} = \frac{11}{3}$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 1} [(x^2 - 1)/(x + 3)]$.', '["$1$", "$-1$", "$1/2$", "$0$"]'::jsonb, 3, 'Since $f(x) = \frac{x^{2} - 1}{x + 3}$ is continuous at $x=1$ (the denominator, if any, is not zero there), substitute directly: $\lim_{x \to 1} \frac{x^{2} - 1}{x + 3} = \frac{1^{2} - 1}{1 + 3} = 0$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 3} [5x - 7]$.', '["$8$", "$9$", "$-8$", "$5$"]'::jsonb, 0, 'Since $f(x) = 5 x - 7$ is continuous at $x=3$ (the denominator, if any, is not zero there), substitute directly: $\lim_{x \to 3} 5 x - 7 = 5 \cdot 3 - 7 = 8$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to -2} [(x^2 + 2x)/(x + 5)]$.', '["$0$", "$1$", "$-1$", "$-2/3$"]'::jsonb, 0, 'Since $f(x) = \frac{x^{2} + 2 x}{x + 5}$ is continuous at $x=-2$ (the denominator, if any, is not zero there), substitute directly: $\lim_{x \to -2} \frac{x^{2} + 2 x}{x + 5} = \frac{\left(-2\right) \left(2 + -2\right)}{-2 + 5} = 0$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 3} [(x^2 - 9)/(x - 3)]$.', '["$0$", "$8$", "$6$", "does not exist ($\\infty$)"]'::jsonb, 2, 'Direct substitution gives $\frac{0}{0}$, a $0/0$ form. Factor: $\dfrac{x^{2} - 9}{x - 3} = \dfrac{\left(x - 3\right) \left(x + 3\right)}{x - 3}$, and cancel the common factor to get $x + 3$ (valid for $x \neq 3$). Substituting $x=3$: $3 + 3 = 6$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 2} [(x^2 - 4)/(x - 2)]$.', '["$4$", "$6$", "$0$", "does not exist ($\\infty$)"]'::jsonb, 0, 'Direct substitution gives $\frac{0}{0}$, a $0/0$ form. Factor: $\dfrac{x^{2} - 4}{x - 2} = \dfrac{\left(x - 2\right) \left(x + 2\right)}{x - 2}$, and cancel the common factor to get $x + 2$ (valid for $x \neq 2$). Substituting $x=2$: $2 + 2 = 4$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 2} [(x^2 - 5x + 6)/(x - 2)]$.', '["does not exist ($\\infty$)", "$-1$", "$0$", "$1$"]'::jsonb, 1, 'Direct substitution gives $\frac{0}{0}$, a $0/0$ form. Factor: $\dfrac{x^{2} - 5 x + 6}{x - 2} = \dfrac{\left(x - 3\right) \left(x - 2\right)}{x - 2}$, and cancel the common factor to get $x - 3$ (valid for $x \neq 2$). Substituting $x=2$: $2 - 3 = -1$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 1} [(x^2 - 1)/(x - 1)]$.', '["$4$", "does not exist ($\\infty$)", "$2$", "$0$"]'::jsonb, 2, 'Direct substitution gives $\frac{0}{0}$, a $0/0$ form. Factor: $\dfrac{x^{2} - 1}{x - 1} = \dfrac{\left(x - 1\right) \left(x + 1\right)}{x - 1}$, and cancel the common factor to get $x + 1$ (valid for $x \neq 1$). Substituting $x=1$: $1 + 1 = 2$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 2} [(x^3 - 8)/(x - 2)]$.', '["does not exist ($\\infty$)", "$0$", "$14$", "$12$"]'::jsonb, 3, 'Direct substitution gives $\frac{0}{0}$, a $0/0$ form. Factor: $\dfrac{x^{3} - 8}{x - 2} = \dfrac{\left(x - 2\right) \left(x^{2} + 2 x + 4\right)}{x - 2}$, and cancel the common factor to get $x^{2} + 2 x + 4$ (valid for $x \neq 2$). Substituting $x=2$: $2^{2} + 2 \cdot 2 + 4 = 12$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 2} [(x^2 + x - 6)/(x - 2)]$.', '["does not exist ($\\infty$)", "$7$", "$5$", "$0$"]'::jsonb, 2, 'Direct substitution gives $\frac{0}{0}$, a $0/0$ form. Factor: $\dfrac{x^{2} + x - 6}{x - 2} = \dfrac{\left(x - 2\right) \left(x + 3\right)}{x - 2}$, and cancel the common factor to get $x + 3$ (valid for $x \neq 2$). Substituting $x=2$: $2 + 3 = 5$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to \infty} [(2x^2 + 3x)/(5x^2 - x + 1)]$.', '["$2/5$", "$\\infty$ (does not exist)", "$1$", "$0$"]'::jsonb, 0, 'Divide numerator and denominator by $x^{2}$, the highest power of $x$ present: $\dfrac{x \left(2 x + 3\right)}{5 x^{2} - x + 1} = \dfrac{2 + \frac{3}{x}}{5 - \frac{1}{x} + \frac{1}{x^{2}}}$. As $x \to \infty$, every term with $x$ in the denominator goes to $0$, leaving $\lim_{x \to \infty} \frac{2 x^{2} + 3 x}{5 x^{2} - x + 1} = \frac{2}{5}$.', 'Limit at Infinity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to \infty} [(3x + 1)/(6x + 5)]$.', '["$1/2$", "$0$", "$1$", "$\\infty$ (does not exist)"]'::jsonb, 0, 'Divide numerator and denominator by $x^{1}$, the highest power of $x$ present: $\dfrac{3 x + 1}{6 x + 5} = \dfrac{3 + \frac{1}{x}}{6 + \frac{5}{x}}$. As $x \to \infty$, every term with $x$ in the denominator goes to $0$, leaving $\lim_{x \to \infty} \frac{3 x + 1}{6 x + 5} = \frac{1}{2}$.', 'Limit at Infinity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to \infty} [(x^2 + 1)/(x^3 + 2)]$.', '["$-1$", "$0$", "$1$", "$\\infty$ (does not exist)"]'::jsonb, 1, 'Divide numerator and denominator by $x^{3}$, the highest power of $x$ present: $\dfrac{x^{2} + 1}{x^{3} + 2} = \dfrac{\frac{1}{x} + \frac{1}{x^{3}}}{1 + \frac{2}{x^{3}}}$. As $x \to \infty$, every term with $x$ in the denominator goes to $0$, leaving $\lim_{x \to \infty} \frac{x^{2} + 1}{x^{3} + 2} = 0$.', 'Limit at Infinity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to \infty} [(4x^3 - x)/(2x^3 + 7)]$.', '["$2$", "$0$", "$\\infty$ (does not exist)", "$1$"]'::jsonb, 0, 'Divide numerator and denominator by $x^{3}$, the highest power of $x$ present: $\dfrac{x \left(4 x^{2} - 1\right)}{2 x^{3} + 7} = \dfrac{4 - \frac{1}{x^{2}}}{2 + \frac{7}{x^{3}}}$. As $x \to \infty$, every term with $x$ in the denominator goes to $0$, leaving $\lim_{x \to \infty} \frac{4 x^{3} - x}{2 x^{3} + 7} = 2$.', 'Limit at Infinity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to \infty} [(x + 3)/(x^2 - 4)]$.', '["$0$", "$\\infty$ (does not exist)", "$-1$", "$1$"]'::jsonb, 0, 'Divide numerator and denominator by $x^{2}$, the highest power of $x$ present: $\dfrac{x + 3}{x^{2} - 4} = \dfrac{\frac{1}{x} + \frac{3}{x^{2}}}{1 - \frac{4}{x^{2}}}$. As $x \to \infty$, every term with $x$ in the denominator goes to $0$, leaving $\lim_{x \to \infty} \frac{x + 3}{x^{2} - 4} = 0$.', 'Limit at Infinity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = 3-x$ for $x < 2$ and $f(x) = x^2-1$ for $x \geq 2$, find $\lim_{x \to 2⁻}$  f(x).', '["$1$", "$3$", "$0$", "$-1$"]'::jsonb, 0, 'Approaching $x=2$ from below, $x < 2$ applies, so $f(x) = 3 - x$ is the relevant branch. The left-hand limit is $\lim_{x \to 2^-} f(x) = 3 - 2 = 1$.', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = 3-x$ for $x < 2$ and $f(x) = x^2-1$ for $x \geq 2$, find $\lim_{x \to 2⁺}$  f(x).', '["$3$", "$4$", "$1$", "$0$"]'::jsonb, 0, 'Approaching $x=2$ from above, $x \geq 2$ applies, so $f(x) = x^{2} - 1$ is the relevant branch. The right-hand limit is $\lim_{x \to 2^+} f(x) = 2^{2} - 1 = 3$.', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For the greatest integer function $f(x) = [x]$, find $\lim_{x \to 3⁻}$  f(x).', '["$4$", "$2$", "$3$", "$0$"]'::jsonb, 1, 'Just below $3$, on the interval $[2, 3)$, the greatest integer function $[x]$ stays constant at $2$ — it only steps up to $3$ once $x$ reaches $3$ itself. So the left-hand limit is $\lim_{x \to 3^-} [x] = 2$.', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For the greatest integer function $f(x) = [x]$, find $\lim_{x \to 3⁺}$  f(x).', '["$2$", "$3$", "$0$", "$4$"]'::jsonb, 1, 'At $x=3$ and just above it, on the interval $[3, 4)$, the greatest integer function $[x]$ equals $3$. So the right-hand limit is $\lim_{x \to 3^+} [x] = 3$.', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 0} [\sin(4x)/x]$.', '["$4$", "does not exist", "$1$", "$0$"]'::jsonb, 0, 'Rewrite $\dfrac{\sin(4x)}{x}$ as $4 \cdot \dfrac{\sin(4x)}{4x}$. Using $\lim_{x \to 0} \dfrac{\sin(kx)}{kx} = 1$ with $k=4$, the second factor tends to $1$, leaving $\lim_{x \to 0} \dfrac{\sin(4x)}{x} = 4 \cdot 1 = 4$.', 'Limits of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 0} [\sin(3x)/(5x)]$.', '["$3/5$", "$1$", "$0$", "$5/3$"]'::jsonb, 0, 'Rewrite $\dfrac{\sin(3x)}{5x}$ as $\frac{3}{5} \cdot \dfrac{\sin(3x)}{3x}$. Using $\lim_{x \to 0} \dfrac{\sin(kx)}{kx} = 1$ with $k=3$, the second factor tends to $1$, leaving $\lim_{x \to 0} \dfrac{\sin(3x)}{5x} = \frac{3}{5} \cdot 1 = \frac{3}{5}$.', 'Limits of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 0} [(1-cos x)/x]$.', '["$1$", "$0$", "does not exist", "$1/2$"]'::jsonb, 1, 'Using the standard limit $\lim_{x \to 0} \dfrac{\cos(x) - 1}{x} = 0$ (equivalently $\lim_{x \to 0} \dfrac{1 - \cos(x)}{x} = 0$, since $1-\cos x$ is a sign flip of $\cos x - 1$): $\lim_{x \to 0} \frac{1 - \cos{\left(x \right)}}{x} = 0$.', 'Limits of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 0} [x \cdot \sin(1/x)]$.', '["$0$", "$1$", "does not exist", "$\\infty$"]'::jsonb, 0, '$-1 \leq \sin(1/x) \leq 1$ for every $x \neq 0$, so multiplying through by $|x|$ gives $-|x| \leq x\sin(1/x) \leq |x|$. As $x \to 0$, both bounds $-|x|$ and $|x|$ tend to $0$, so by the Sandwich (Squeeze) Theorem, $\lim_{x \to 0} x\sin(1/x) = 0$.', 'Some Theorems on Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = (x^2-25)/(x-5)$ if $x \neq 5$, and $f(5)$$=10$, is f continuous at x=5?', '["No — removable discontinuity", "No — jump discontinuity", "No — essential discontinuity", "Yes — f is continuous at x=5"]'::jsonb, 3, 'Simplify: $\frac{x^{2} - 25}{x - 5} = x + 5$ for $x \neq 5$, so $\lim_{x \to 5} f(x) = 5 + 5 = 10$. This equals the given $f(5) = 10$, and since the limit exists and matches $f(5)$, $f$ is continuous at $x=5$.', 'Continuous Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = (x^2-25)/(x-5)$ if $x \neq 5$, and $f(5)$$=7$, is f continuous at x=5?', '["No — essential discontinuity", "Yes — f is continuous at x=5", "No — removable discontinuity", "No — jump discontinuity"]'::jsonb, 2, 'Simplify: $\frac{x^{2} - 25}{x - 5} = x + 5$ for $x \neq 5$, so $\lim_{x \to 5} f(x) = 5 + 5 = 10$, but the given $f(5) = 7 \neq 10$. The limit exists but does not equal $f(5)$, so $f$ is discontinuous at $x=5$.', 'Types of Discontinuities', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = x^5$.', '["$5x^5$", "$5x^4$", "$20x^3$", "$x^5$"]'::jsonb, 1, 'Differentiate term by term: $\dfrac{d}{dx}[x^{5}] = 5 x^{4} = 5 x^{4}$. Summing the terms: $f''(x) = 5 x^{4}$.', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = 3x^4$.', '["$12x^3$", "$3x^4$", "$12x^4$", "$36x^2$"]'::jsonb, 0, 'Differentiate term by term: $\dfrac{d}{dx}[3 \cdot x^{4}] = 3 \cdot 4 x^{3} = 12 x^{3}$. Summing the terms: $f''(x) = 12 x^{3}$.', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = 7x^3 - 2x^2 + x$.', '["$7x^3 - 2x^2 + x$", "$21x^3 - 4x^2 + x$", "$42x - 4$", "$21x^2 - 4x + 1$"]'::jsonb, 3, 'Differentiate term by term: $\dfrac{d}{dx}[7 \cdot x^{3}] = 7 \cdot 3 x^{2} = 21 x^{2}$; $\dfrac{d}{dx}[-2 \cdot x^{2}] = -2 \cdot 2 x^{1} = - 4 x$; $\dfrac{d}{dx}[x^{1}] = 1 x^{0} = 1$. Summing the terms: $f''(x) = 21 x^{2} - 4 x + 1$.', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = x^6 - 4x$.', '["$30x^4$", "$6x^5 - 4$", "$x^6 - 4x$", "$6x^6 - 4x$"]'::jsonb, 1, 'Differentiate term by term: $\dfrac{d}{dx}[x^{6}] = 6 x^{5} = 6 x^{5}$; $\dfrac{d}{dx}[-4 \cdot x^{1}] = -4 \cdot 1 x^{0} = -4$. Summing the terms: $f''(x) = 6 x^{5} - 4$.', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = 2x^7 + 5$.', '["$14x^6$", "$14x^7$", "$84x^5$", "$2x^7 + 5$"]'::jsonb, 0, 'Differentiate term by term: $\dfrac{d}{dx}[2 \cdot x^{7}] = 2 \cdot 7 x^{6} = 14 x^{6}$; the derivative of the constant $5$ is $0$. Summing the terms: $f''(x) = 14 x^{6}$.', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = x^2/2 - 3x$.', '["$1$", "$x - 3$", "$x^2/2 - 3x$", "$x^2 - 3x$"]'::jsonb, 1, 'Differentiate term by term: $\dfrac{d}{dx}[\frac{1}{2} \cdot x^{2}] = \frac{1}{2} \cdot 2 x^{1} = x$; $\dfrac{d}{dx}[-3 \cdot x^{1}] = -3 \cdot 1 x^{0} = -3$. Summing the terms: $f''(x) = x - 3$.', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \sin(x)$.', '["$\\cos(x) + 1$", "$\\cos(x)$", "$\\sin(x)$", "$-\\cos(x)$"]'::jsonb, 1, 'Differentiate term by term: $\dfrac{d}{dx}[\sin(x)] = \cos(x)$. Summing the terms: $f''(x) = \cos{\left(x \right)}$.', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \cos(x)$.', '["$\\sin(x)$", "$-\\sin(x)$", "$\\cos(x)$", "$1 - \\sin(x)$"]'::jsonb, 1, 'Differentiate term by term: $\dfrac{d}{dx}[\cos(x)] = -\sin(x)$. Summing the terms: $f''(x) = - \sin{\left(x \right)}$.', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \tan(x)$.', '["$-1/\\cos(x)^2$", "$\\tan(x)$", "$\\cos(x)$", "$\\cos(x)^{-2}$"]'::jsonb, 3, 'Differentiate term by term: $\dfrac{d}{dx}[\tan{\left(x \right)}] = \tan^{2}{\left(x \right)} + 1$. Summing the terms: $f''(x) = 1 + \tan^{2}{\left(x \right)}$.', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = 3 \sin(x)$.', '["$\\cos(x)$", "$-3 \\cos(x)$", "$3 \\cos(x)$", "$3 \\sin(x)$"]'::jsonb, 2, 'Differentiate term by term: $\dfrac{d}{dx}[3 \cdot \sin(x)] = 3 \cdot \cos(x)$. Summing the terms: $f''(x) = 3 \cos{\left(x \right)}$.', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \sin(x) + \cos(x)$.', '["$-\\sin(x) + \\cos(x)$", "$\\sin(x) - \\cos(x)$", "$\\sin(x) + \\cos(x)$", "$\\cos(x)$"]'::jsonb, 0, 'Differentiate term by term: $\dfrac{d}{dx}[\sin(x)] = \cos(x)$; $\dfrac{d}{dx}[\cos(x)] = -\sin(x)$. Summing the terms: $f''(x) = \cos{\left(x \right)} - \sin{\left(x \right)}$.', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = x^2 \cdot \sin(x)$.', '["$x(x \\cos(x) + 2 \\sin(x))$", "$x^2 \\cos(x)$", "$2x \\cos(x)$", "$2x \\sin(x)$"]'::jsonb, 0, 'Product Rule: $(uv)'' = u''v + uv''$. With $u = x^{2}$ and $v = \sin{\left(x \right)}$: $u'' = 2 x$ and $v'' = \cos{\left(x \right)}$. So $f''(x) = u''v + uv'' = (2 x)(\sin{\left(x \right)}) + (x^{2})(\cos{\left(x \right)}) = x \left(x \cos{\left(x \right)} + 2 \sin{\left(x \right)}\right)$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = x \cdot \cos(x)$.', '["$-x \\sin(x)$", "$-x \\sin(x) + \\cos(x)$", "$\\cos(x)$", "$-\\sin(x)$"]'::jsonb, 1, 'Product Rule: $(uv)'' = u''v + uv''$. With $u = x$ and $v = \cos{\left(x \right)}$: $u'' = 1$ and $v'' = - \sin{\left(x \right)}$. So $f''(x) = u''v + uv'' = (1)(\cos{\left(x \right)}) + (x)(- \sin{\left(x \right)}) = - x \sin{\left(x \right)} + \cos{\left(x \right)}$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = x^2 \cdot x + 1$.', '["$x^2$", "$2x$", "$2x^2 + 2x$", "$3x^2 + 2x$"]'::jsonb, 3, 'Product Rule: $(uv)'' = u''v + uv''$. With $u = x^{2}$ and $v = x + 1$: $u'' = 2 x$ and $v'' = 1$. So $f''(x) = u''v + uv'' = (2 x)(x + 1) + (x^{2})(1) = x \left(3 x + 2\right)$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \sin(x) \cdot \cos(x)$.', '["$\\cos(2x)$", "$-\\sin(x)^2$", "$\\cos(x)^2$", "$-\\sin(2x)/2$"]'::jsonb, 0, 'Product Rule: $(uv)'' = u''v + uv''$. With $u = \sin{\left(x \right)}$ and $v = \cos{\left(x \right)}$: $u'' = \cos{\left(x \right)}$ and $v'' = - \sin{\left(x \right)}$. So $f''(x) = u''v + uv'' = (\cos{\left(x \right)})(\cos{\left(x \right)}) + (\sin{\left(x \right)})(- \sin{\left(x \right)}) = \cos{\left(2 x \right)}$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = (x)/(x + 1)$.', '["$1/(x^2 + 2x + 1)$", "$1/(x + 1)$", "$1$", "$2x/(x^2 + 2x + 1) + 1/(x^2 + 2x + 1)$"]'::jsonb, 0, 'Quotient Rule: $(u/v)'' = \dfrac{u''v - uv''}{v^2}$. With $u = x$ and $v = x + 1$: $u'' = 1$ and $v'' = 1$. So $f''(x) = \dfrac{u''v - uv''}{v^2} = \dfrac{(1)(x + 1) - (x)(1)}{(x + 1)^2} = \dfrac{1}{x^{2} + 2 x + 1}$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = (x^2)/(x - 2)$.', '["$x^2/(x^2 - 4x + 4) - 4x/(x^2 - 4x + 4)$", "$2x$", "$2x/(x - 2)$", "$3x^2/(x^2 - 4x + 4) - 4x/(x^2 - 4x + 4)$"]'::jsonb, 0, 'Quotient Rule: $(u/v)'' = \dfrac{u''v - uv''}{v^2}$. With $u = x^{2}$ and $v = x - 2$: $u'' = 2 x$ and $v'' = 1$. So $f''(x) = \dfrac{u''v - uv''}{v^2} = \dfrac{(2 x)(x - 2) - (x^{2})(1)}{(x - 2)^2} = \dfrac{x^{2} - 4 x}{x^{2} - 4 x + 4}$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = (\sin(x))/(x)$.', '["$(x \\cos(x) + \\sin(x))/x^2$", "$(x \\cos(x) - \\sin(x))/x^2$", "$\\cos(x)/x$", "$\\cos(x)$"]'::jsonb, 1, 'Quotient Rule: $(u/v)'' = \dfrac{u''v - uv''}{v^2}$. With $u = \sin{\left(x \right)}$ and $v = x$: $u'' = \cos{\left(x \right)}$ and $v'' = 1$. So $f''(x) = \dfrac{u''v - uv''}{v^2} = \dfrac{(\cos{\left(x \right)})(x) - (\sin{\left(x \right)})(1)}{(x)^2} = \dfrac{x \cos{\left(x \right)} - \sin{\left(x \right)}}{x^{2}}$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = (2x + 1)/(x^2 + 1)$.', '["$1/x$", "$-2x^2/(x^4 + 2x^2 + 1) - 2x/(x^4 + 2x^2 + 1) + 2/(x^4 + 2x^2 + 1)$", "$2/(x^2 + 1)$", "$6x^2/(x^4 + 2x^2 + 1) + 2x/(x^4 + 2x^2 + 1) + 2/(x^4 + 2x^2 + 1)$"]'::jsonb, 1, 'Quotient Rule: $(u/v)'' = \dfrac{u''v - uv''}{v^2}$. With $u = 2 x + 1$ and $v = x^{2} + 1$: $u'' = 2$ and $v'' = 2 x$. So $f''(x) = \dfrac{u''v - uv''}{v^2} = \dfrac{(2)(x^{2} + 1) - (2 x + 1)(2 x)}{(x^{2} + 1)^2} = \dfrac{- 2 x^{2} - 2 x + 2}{x^{4} + 2 x^{2} + 1}$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = (x^2 + 1)^3$.', '["$3x^4 + 6x^2 + 3$", "$6x^5 + 12x^3 + 6x$", "$8x^3$", "$6x^7 + 18x^5 + 18x^3 + 6x$"]'::jsonb, 1, 'Chain Rule: with $u = x^{2} + 1$, $\dfrac{d}{dx}[u^{3}] = 3 u^{2} \cdot u''$. Here $u'' = 2 x$, so $f''(x) = 3(x^{2} + 1)^{2} \cdot (2 x) = 6 x^{5} + 12 x^{3} + 6 x$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = (2x - 5)^4$.', '["$64x^3 - 480x^2 + 1200x - 1000$", "$16$", "$128x^4 - 1280x^3 + 4800x^2 - 8000x + 5000$", "$32x^3 - 240x^2 + 600x - 500$"]'::jsonb, 0, 'Chain Rule: with $u = 2 x - 5$, $\dfrac{d}{dx}[u^{4}] = 4 u^{3} \cdot u''$. Here $u'' = 2$, so $f''(x) = 4(2 x - 5)^{3} \cdot (2) = 64 x^{3} - 480 x^{2} + 1200 x - 1000$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = (x^3 - 2x)^2$.', '["$2x^3 - 4x$", "$9x^4 - 12x^2 + 4$", "$6x^5 - 16x^3 + 8x$", "$6x^8 - 28x^6 + 40x^4 - 16x^2$"]'::jsonb, 2, 'Chain Rule: with $u = x^{3} - 2 x$, $\dfrac{d}{dx}[u^{2}] = 2 u^{1} \cdot u''$. Here $u'' = 3 x^{2} - 2$, so $f''(x) = 2(x^{3} - 2 x)^{1} \cdot (3 x^{2} - 2) = 6 x^{5} - 16 x^{3} + 8 x$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \sin(2x + 3)$.', '["$2 \\cos(2x + 3)$", "$\\cos(2x + 3)$", "$-2 \\cos(2x + 3)$", "$\\sin(2)$"]'::jsonb, 0, 'Chain Rule: with $u = 2 x + 3$, $\dfrac{d}{dx}[\sin(u)] = \cos(u) \cdot u''$. Here $u'' = 2$, so $f''(x) = \cos(2 x + 3) \cdot (2) = 2 \cos{\left(2 x + 3 \right)}$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \sin(x^2)$.', '["$-2x \\cos(x^2)$", "$\\sin(2x)$", "$\\cos(x^2)$", "$2x \\cos(x^2)$"]'::jsonb, 3, 'Chain Rule: with $u = x^{2}$, $\dfrac{d}{dx}[\sin(u)] = \cos(u) \cdot u''$. Here $u'' = 2 x$, so $f''(x) = \cos(x^{2}) \cdot (2 x) = 2 x \cos{\left(x^{2} \right)}$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \sin(3x - 1)$.', '["$\\cos(3x - 1)$", "$-3 \\cos(3x - 1)$", "$3 \\cos(3x - 1)$", "$\\sin(3)$"]'::jsonb, 2, 'Chain Rule: with $u = 3 x - 1$, $\dfrac{d}{dx}[\sin(u)] = \cos(u) \cdot u''$. Here $u'' = 3$, so $f''(x) = \cos(3 x - 1) \cdot (3) = 3 \cos{\left(3 x - 1 \right)}$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent line to $y = x^2 - 4x + 3$ at x = 1.', '["$-2$", "$-1$", "$0$", "$2$"]'::jsonb, 0, 'The slope is $f''(1)$ where $f''(x) = 2 x - 4$, so $f''(1) = 2 \cdot 1 - 4 = -2$.', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent line to $y = x^3 - 3x$ at x = 2.', '["$2$", "$11$", "$-9$", "$9$"]'::jsonb, 3, 'The slope is $f''(2)$ where $f''(x) = 3 x^{2} - 3$, so $f''(2) = 3 \cdot 2^{2} - 3 = 9$.', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent line to $y = 2x^2 + 1$ at x = -1.', '["$-4$", "$3$", "$-2$", "$4$"]'::jsonb, 0, 'The slope is $f''(-1)$ where $f''(x) = 4 x$, so $f''(-1) = 4 \left(-1\right) = -4$.', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent line to $y = x^2$ at x = 3.', '["$9$", "$6$", "$-6$", "$8$"]'::jsonb, 1, 'The slope is $f''(3)$ where $f''(x) = 2 x$, so $f''(3) = 2 \cdot 3 = 6$.', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $x^2$ + $y^2$ = 25, find dy/dx at the point (3,4).', '["$4/3$", "$-4/3$", "$3/4$", "$-3/4$"]'::jsonb, 3, 'Differentiate both sides of $x^{2} + y^{2} = 25$ implicitly with respect to $x$, treating $y$ as a function of $x$: $2 x + 2 y(dy/dx) = 0$. Solving for $dy/dx$: $dy/dx = - \frac{x}{y}$. At $(3,4)$: $dy/dx = - \frac{3}{4} = - \frac{3}{4}$.', 'Implicit Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $x^3$ + $y^3$ = 9, find dy/dx at the point (1,2).', '["$1/4$", "$-4$", "$4$", "$-1/4$"]'::jsonb, 3, 'Differentiate both sides of $x^{3} + y^{3} = 9$ implicitly with respect to $x$, treating $y$ as a function of $x$: $3 x^{2} + 3 y^{2}(dy/dx) = 0$. Solving for $dy/dx$: $dy/dx = - \frac{x^{2}}{y^{2}}$. At $(1,2)$: $dy/dx = - \frac{1}{4} = - \frac{1}{4}$.', 'Implicit Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the critical point(s) of $f(x) = x^3 - 3x + 1$.', '["$0$", "$-1, 1$", "no critical points", "$0, 2$"]'::jsonb, 1, '$f''(x) = 3 x^{2} - 3$. Setting $f''(x) = 0$: $3 x^{2} - 3 = 0$, which gives $x = -1, 1$.', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the critical point(s) of $f(x) = x^2 - 6x + 5$.', '["no critical points", "$3$", "$4$", "$2$"]'::jsonb, 1, '$f''(x) = 2 x - 6$. Setting $f''(x) = 0$: $2 x - 6 = 0$, which gives $x = 3$.', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the critical point(s) of $f(x) = 2x^3 - 3x^2 - 12x + 4$.', '["$0, 3$", "$0$", "no critical points", "$-1, 2$"]'::jsonb, 3, '$f''(x) = 6 x^{2} - 6 x - 12$. Setting $f''(x) = 0$: $6 x^{2} - 6 x - 12 = 0$, which gives $x = -1, 2$.', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the critical point(s) of $f(x) = x^3 - 12x$.', '["$-2, 2$", "$-1, 3$", "$0$", "no critical points"]'::jsonb, 0, '$f''(x) = 3 x^{2} - 12$. Setting $f''(x) = 0$: $3 x^{2} - 12 = 0$, which gives $x = -2, 2$.', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'At the critical point x = 1 of $f(x) = x^3 - 3x$, the point is a:', '["point of inflection", "relative maximum", "not a critical point", "relative minimum"]'::jsonb, 3, '$f''''(x) = 6 x$, so $f''''(1) = 6 \cdot 1 = 6$, which is positive, indicating a relative minimum.', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'At the critical point x = -1 of $f(x) = x^3 - 3x$, the point is a:', '["relative minimum", "not a critical point", "relative maximum", "point of inflection"]'::jsonb, 2, '$f''''(x) = 6 x$, so $f''''(-1) = 6 \left(-1\right) = -6$, which is negative, indicating a relative maximum.', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'At the critical point x = 2 of $f(x) = x^2 - 4x + 7$, the point is a:', '["relative maximum", "not a critical point", "relative minimum", "point of inflection"]'::jsonb, 2, '$f''''(x) = 2$, so $f''''(2) = 2 = 2$, which is positive, indicating a relative minimum.', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'At the critical point x = 3 of $f(x) = -x^2 + 6x - 5$, the point is a:', '["not a critical point", "relative maximum", "relative minimum", "point of inflection"]'::jsonb, 1, '$f''''(x) = -2$, so $f''''(3) = -2 = -2$, which is negative, indicating a relative maximum.', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^2 - 4x + 3$, on which interval is f increasing?', '["$(2, \\infty)$", "$(-\\infty, \\infty)$", "$(0, 2)$", "$(-\\infty, 2)$"]'::jsonb, 0, '$f''(x) = 2 \left(x - 2\right)$. Solving $f''(x) > 0$ shows $f''(x)$ is positive for $x \in \left(2, \infty\right)$, so $f$ is increasing on $\left(2, \infty\right)$.', 'Monotonicity of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^3 - 3x$, on which interval is f decreasing?', '["$(-\\infty, \\infty)$", "$(-\\infty,-1)$", "$(-1, 1)$", "$(1, \\infty)$"]'::jsonb, 2, '$f''(x) = 3 \left(x - 1\right) \left(x + 1\right)$. Solving $f''(x) < 0$ shows $f''(x)$ is negative for $x \in \left(-1, 1\right)$, so $f$ is decreasing on $\left(-1, 1\right)$.', 'Monotonicity of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent line to $y = x^2$ at x = -1.', '["$y = -2x + 1$", "$y = -2x - 1$", "$y = 1x - 2$", "$y = 2x - 1$"]'::jsonb, 1, '$f(-1) = 1$, $f''(-1) = -2$. Using the point-slope form $y - f(a) = f''(a)(x-a)$: $y - 1 = -2(x - -1)$, which simplifies to $y = -2x - 1$.', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent line to $y = x^2 - 3x + 2$ at x = 1.', '["$y = 0x - 1$", "$y = 1x + 1$", "$y = -1x + 1$", "$y = -1x$"]'::jsonb, 2, '$f(1) = 0$, $f''(1) = -1$. Using the point-slope form $y - f(a) = f''(a)(x-a)$: $y - 0 = -1(x - 1)$, which simplifies to $y = -1x + 1$.', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent line to $y = x^3$ at x = 1.', '["$y = -3x - 2$", "$y = 3x + 1$", "$y = 3x - 2$", "$y = 1x + 3$"]'::jsonb, 2, '$f(1) = 1$, $f''(1) = 3$. Using the point-slope form $y - f(a) = f''(a)(x-a)$: $y - 1 = 3(x - 1)$, which simplifies to $y = 3x - 2$.', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent line to $y = x^2$ at x = 3.', '["$y = -6x - 9$", "$y = 9x + 6$", "$y = 6x + 9$", "$y = 6x - 9$"]'::jsonb, 3, '$f(3) = 9$, $f''(3) = 6$. Using the point-slope form $y - f(a) = f''(a)(x-a)$: $y - 9 = 6(x - 3)$, which simplifies to $y = 6x - 9$.', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 0} [\sin(x)/x]$.', '["$1$", "does not exist", "$\\infty$", "$0$"]'::jsonb, 0, 'This is a $0/0$ form. Differentiate numerator and denominator separately: $\dfrac{d}{dx}[\sin{\left(x \right)}] = \cos{\left(x \right)}$ and $\dfrac{d}{dx}[x] = 1$. By L''Hopital''s Rule, $\lim_{x \to 0} \frac{\sin{\left(x \right)}}{x} = \lim_{x \to 0} \dfrac{\cos{\left(x \right)}}{1} = \cos{\left(0 \right)} = 1$.', 'Indeterminate Forms and L''Hopital''s Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 1} [(x^2 - 1)/(x - 1)]$.', '["$2$", "$\\infty$", "$0$", "does not exist"]'::jsonb, 0, 'This is a $0/0$ form. Differentiate numerator and denominator separately: $\dfrac{d}{dx}[x^{2} - 1] = 2 x$ and $\dfrac{d}{dx}[x - 1] = 1$. By L''Hopital''s Rule, $\lim_{x \to 1} \frac{x^{2} - 1}{x - 1} = \lim_{x \to 1} \dfrac{2 x}{1} = 2 \cdot 1 = 2$.', 'Indeterminate Forms and L''Hopital''s Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 0} [(1 - \cos(x))/x^2]$.', '["does not exist", "$\\infty$", "$1/2$", "$0$"]'::jsonb, 2, 'This is a $0/0$ form. Differentiate numerator and denominator separately: $\dfrac{d}{dx}[1 - \cos{\left(x \right)}] = \sin{\left(x \right)}$ and $\dfrac{d}{dx}[x^{2}] = 2 x$. By L''Hopital''s Rule, $\lim_{x \to 0} \frac{1 - \cos{\left(x \right)}}{x^{2}} = \lim_{x \to 0} \dfrac{\sin{\left(x \right)}}{2 x} = \frac{\sin{\left(0 \right)}}{2 \cdot 0} = \frac{1}{2}$.', 'Indeterminate Forms and L''Hopital''s Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 2} [(x^2 - 4)/(x - 2)]$.', '["$0$", "$\\infty$", "$4$", "does not exist"]'::jsonb, 2, 'This is a $0/0$ form. Differentiate numerator and denominator separately: $\dfrac{d}{dx}[x^{2} - 4] = 2 x$ and $\dfrac{d}{dx}[x - 2] = 1$. By L''Hopital''s Rule, $\lim_{x \to 2} \frac{x^{2} - 4}{x - 2} = \lim_{x \to 2} \dfrac{2 x}{1} = 2 \cdot 2 = 4$.', 'Indeterminate Forms and L''Hopital''s Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^3 - 6x^2 + 9x$, find the x-coordinate of the point of inflection.', '["$-2$", "$3$", "$0$", "$2$"]'::jsonb, 3, '$f''''(x) = 6 \left(x - 2\right)$. Setting $f''''(x)=0$ gives $x=2$, where the sign of $f''''(x)$ changes, so concavity changes there.', 'Concavity and Points of Inflection', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^4 - 2x^2$, on which interval is f concave up?', '["$x < -1/$$\\sqrt{3}$ or $x > 1/$$\\sqrt{3}$", "$-1/\\sqrt{3} < x < 1/\\sqrt{3}$", "all real x", "no interval"]'::jsonb, 0, '$f''''(x) = 4 \left(3 x^{2} - 1\right)$. Setting $f''''(x) > 0$ gives $\left(-\infty, - \frac{\sqrt{3}}{3}\right) \cup \left(\frac{\sqrt{3}}{3}, \infty\right)$.', 'Concavity and Points of Inflection', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int 3x^2 \, dx$.', '["$x^3 + C$", "$6x + C$", "$3x^2 + C$", "$2x^3 + C$"]'::jsonb, 0, 'Integrate term by term using the power rule for antiderivatives ($\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$) and the standard trigonometric antiderivatives: $\int 3 \cdot x^{2} \, dx = 3 \cdot \dfrac{x^{3}}{3}$. Summing the terms and adding the constant of integration: $\int f(x) \, dx = x^{3} + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int 4x^3 - 2x \, dx$.', '["$2x^4 - 2x^2 + C$", "$4x^3 - 2x + C$", "$12x^2 - 2 + C$", "$x^4 - x^2 + C$"]'::jsonb, 3, 'Integrate term by term using the power rule for antiderivatives ($\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$) and the standard trigonometric antiderivatives: $\int 4 \cdot x^{3} \, dx = 4 \cdot \dfrac{x^{4}}{4}$; $\int -2 \cdot x^{1} \, dx = -2 \cdot \dfrac{x^{2}}{2}$. Summing the terms and adding the constant of integration: $\int f(x) \, dx = x^{4} - x^{2} + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int x^4 + 5x^2 \, dx$.', '["$4x^3 + 10x + C$", "$2x^5/5 + 10x^3/3 + C$", "$x^4 + 5x^2 + C$", "$x^5/5 + 5x^3/3 + C$"]'::jsonb, 3, 'Integrate term by term using the power rule for antiderivatives ($\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$) and the standard trigonometric antiderivatives: $\int x^{4} \, dx = \dfrac{x^{5}}{5}$; $\int 5 \cdot x^{2} \, dx = 5 \cdot \dfrac{x^{3}}{3}$. Summing the terms and adding the constant of integration: $\int f(x) \, dx = \frac{x^{5}}{5} + \frac{5 x^{3}}{3} + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int 6x^5 - 3 \, dx$.', '["$6x^5 - 3 + C$", "$x^6 - 3x + C$", "$30x^4 + C$", "$2x^6 - 6x + C$"]'::jsonb, 1, 'Integrate term by term using the power rule for antiderivatives ($\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$) and the standard trigonometric antiderivatives: $\int 6 \cdot x^{5} \, dx = 6 \cdot \dfrac{x^{6}}{6}$; $\int -3 \, dx = -3x$. Summing the terms and adding the constant of integration: $\int f(x) \, dx = x^{6} - 3 x + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int 2x + 7 \, dx$.', '["$2 + C$", "$x^2 + 7x + C$", "$2x^2 + 14x + C$", "$2x + 7 + C$"]'::jsonb, 1, 'Integrate term by term using the power rule for antiderivatives ($\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$) and the standard trigonometric antiderivatives: $\int 2 \cdot x^{1} \, dx = 2 \cdot \dfrac{x^{2}}{2}$; $\int 7 \, dx = 7x$. Summing the terms and adding the constant of integration: $\int f(x) \, dx = x^{2} + 7 x + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int \sin(x) \, dx$.', '["$\\sec(x) + C$", "$-\\sin(x) + C$", "$-\\cos(x) + C$", "$\\cos(x) + C$"]'::jsonb, 2, 'Integrate term by term using the power rule for antiderivatives ($\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$) and the standard trigonometric antiderivatives: $\int \sin(x) \, dx = -\cos(x)$. Summing the terms and adding the constant of integration: $\int f(x) \, dx = - \cos{\left(x \right)} + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int \cos(x) \, dx$.', '["$\\cos(x) + C$", "$\\sin(x) + C$", "$-\\sin(x) + C$", "$\\sec(x) + C$"]'::jsonb, 1, 'Integrate term by term using the power rule for antiderivatives ($\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$) and the standard trigonometric antiderivatives: $\int \cos(x) \, dx = \sin(x)$. Summing the terms and adding the constant of integration: $\int f(x) \, dx = \sin{\left(x \right)} + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int \sec(x)^2 \, dx$.', '["$\\tan(x) + C$", "$-\\tan(x) + C$", "$\\sec(x)\\tan(x) + C$", "$\\cot(x) + C$"]'::jsonb, 0, 'Integrate term by term using the power rule for antiderivatives ($\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$) and the standard trigonometric antiderivatives: $\int \sec^2(x) \, dx = \tan(x)$. Summing the terms and adding the constant of integration: $\int f(x) \, dx = \frac{\sin{\left(x \right)}}{\cos{\left(x \right)}} + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int 3 \sin(x) \, dx$.', '["$-3 \\cos(x) + C$", "$\\sec(x) + C$", "$-3 \\sin(x) + C$", "$3 \\cos(x) + C$"]'::jsonb, 0, 'Integrate term by term using the power rule for antiderivatives ($\int x^n \, dx = \dfrac{x^{n+1}}{n+1}$) and the standard trigonometric antiderivatives: $\int 3 \cdot \sin(x) \, dx = 3 \cdot -\cos(x)$. Summing the terms and adding the constant of integration: $\int f(x) \, dx = - 3 \cos{\left(x \right)} + C$.', 'Antiderivatives of Some Elementary Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{0}^{2} x^2 \, dx$.', '["$5/3$", "$-8/3$", "$8/3$", "$11/3$"]'::jsonb, 2, 'An antiderivative is $F(x) = \frac{x^{3}}{3}$. By the Fundamental Theorem, $\int_{0}^{2} x^{2} \, dx = F(2) - F(0) = (\frac{2^{3}}{3} = \frac{8}{3}) - (\frac{0^{3}}{3} = 0) = \frac{8}{3} - 0 = \frac{8}{3}$.', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{1}^{4} 3x - 1 \, dx$.', '["$41/2$", "$-39/2$", "$20$", "$39/2$"]'::jsonb, 3, 'An antiderivative is $F(x) = \frac{3 x^{2}}{2} - x$. By the Fundamental Theorem, $\int_{1}^{4} 3 x - 1 \, dx = F(4) - F(1) = (\frac{4 \left(-2 + 3 \cdot 4\right)}{2} = 20) - (\frac{1 \left(-2 + 3 \cdot 1\right)}{2} = \frac{1}{2}) = 20 - \frac{1}{2} = \frac{39}{2}$.', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{0}^{3} x^2 - 4x + 3 \, dx$.', '["$-1$", "$2$", "$0$", "$1$"]'::jsonb, 2, 'An antiderivative is $F(x) = \frac{x^{3}}{3} - 2 x^{2} + 3 x$. By the Fundamental Theorem, $\int_{0}^{3} x^{2} - 4 x + 3 \, dx = F(3) - F(0) = (\frac{3 \left(9 - 6 \cdot 3 + 3^{2}\right)}{3} = 0) - (\frac{0 \left(9 - 6 \cdot 0 + 0^{2}\right)}{3} = 0) = 0 - 0 = 0$.', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{-1}^{2} 2x + 1 \, dx$.', '["$7$", "$5$", "$6$", "$-6$"]'::jsonb, 2, 'An antiderivative is $F(x) = x^{2} + x$. By the Fundamental Theorem, $\int_{-1}^{2} 2 x + 1 \, dx = F(2) - F(-1) = (2^{2} + 2 = 6) - (\left(-1\right)^{2} + -1 = 0) = 6 - 0 = 6$.', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{0}^{1} x^3 \, dx$.', '["$-3/4$", "$1/4$", "$-1/4$", "$5/4$"]'::jsonb, 1, 'An antiderivative is $F(x) = \frac{x^{4}}{4}$. By the Fundamental Theorem, $\int_{0}^{1} x^{3} \, dx = F(1) - F(0) = (\frac{1^{4}}{4} = \frac{1}{4}) - (\frac{0^{4}}{4} = 0) = \frac{1}{4} - 0 = \frac{1}{4}$.', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{-1}^{1} 4 - x^2 \, dx$.', '["$-22/3$", "$22/3$", "$25/3$", "$11/3$"]'::jsonb, 1, 'An antiderivative is $F(x) = - \frac{x^{3}}{3} + 4 x$. By the Fundamental Theorem, $\int_{-1}^{1} 4 - x^{2} \, dx = F(1) - F(-1) = (\frac{1 \left(12 - 1^{2}\right)}{3} = \frac{11}{3}) - (\frac{\left(-1\right) \left(12 - \left(-1\right)^{2}\right)}{3} = - \frac{11}{3}) = \frac{11}{3} - - \frac{11}{3} = \frac{22}{3}$.', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = x^2$, the x-axis, $x=0$, and x=2.', '["$16/3$", "$11/3$", "$-8/3$", "$8/3$"]'::jsonb, 3, '$y=x^{2}$ does not cross the $x$-axis between $x=0$ and $x=2$, so the area is $\int_{0}^{2} x^{2} \, dx$. An antiderivative is $F(x) = \frac{x^{3}}{3}$, so the area is $F(2) - F(0) = \frac{2^{3}}{3} - (\frac{0^{3}}{3}) = \frac{8}{3}$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = 3x$, the x-axis, $x=0$, and x=4.', '["$-24$", "$25$", "$48$", "$24$"]'::jsonb, 3, '$y=3 x$ does not cross the $x$-axis between $x=0$ and $x=4$, so the area is $\int_{0}^{4} 3 x \, dx$. An antiderivative is $F(x) = \frac{3 x^{2}}{2}$, so the area is $F(4) - F(0) = \frac{3 \cdot 4^{2}}{2} - (\frac{3 \cdot 0^{2}}{2}) = 24$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = 4 - x^2$, the x-axis, $x=-2$, and x=2.', '["$32/3$", "$-32/3$", "$35/3$", "$64/3$"]'::jsonb, 0, '$y=4 - x^{2}$ does not cross the $x$-axis between $x=-2$ and $x=2$, so the area is $\int_{-2}^{2} 4 - x^{2} \, dx$. An antiderivative is $F(x) = - \frac{x^{3}}{3} + 4 x$, so the area is $F(2) - F(-2) = \frac{2 \left(12 - 2^{2}\right)}{3} - (\frac{\left(-2\right) \left(12 - \left(-2\right)^{2}\right)}{3}) = \frac{32}{3}$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = x^3$, the x-axis, $x=0$, and x=2.', '["$8$", "$-4$", "$4$", "$5$"]'::jsonb, 2, '$y=x^{3}$ does not cross the $x$-axis between $x=0$ and $x=2$, so the area is $\int_{0}^{2} x^{3} \, dx$. An antiderivative is $F(x) = \frac{x^{4}}{4}$, so the area is $F(2) - F(0) = \frac{2^{4}}{4} - (\frac{0^{4}}{4}) = 4$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = x + 3$ and $y = x^2 - 1 between x=-1$ and x=1.', '["$6$", "$-22/3$", "$22/3$", "$28/3$"]'::jsonb, 2, 'Between $x=-1$ and $x=1$, $y=x + 3$ lies above $y=x^{2} - 1$, so the area is $\int_{-1}^{1} [(x + 3) - (x^{2} - 1)] \, dx = \int_{-1}^{1} - x^{2} + x + 4 \, dx$. An antiderivative is $F(x) = - \frac{x^{3}}{3} + \frac{x^{2}}{2} + 4 x$, so the area is $F(1) - F(-1) = \frac{1 \left(24 + 3 \cdot 1 - 2 \cdot 1^{2}\right)}{6} - (\frac{\left(-1\right) \left(24 + 3 \left(-1\right) - 2 \left(-1\right)^{2}\right)}{6}) = \frac{22}{3}$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = 6 - x$ and $y = x^2 between x=-3$ and x=2.', '["$65/2$", "$-125/6$", "$137/6$", "$125/6$"]'::jsonb, 3, 'Between $x=-3$ and $x=2$, $y=6 - x$ lies above $y=x^{2}$, so the area is $\int_{-3}^{2} [(6 - x) - (x^{2})] \, dx = \int_{-3}^{2} - x^{2} - x + 6 \, dx$. An antiderivative is $F(x) = - \frac{x^{3}}{3} - \frac{x^{2}}{2} + 6 x$, so the area is $F(2) - F(-3) = \frac{2 \left(36 - 3 \cdot 2 - 2 \cdot 2^{2}\right)}{6} - (\frac{\left(-3\right) \left(36 - 3 \left(-3\right) - 2 \left(-3\right)^{2}\right)}{6}) = \frac{125}{6}$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = x + 5$ and $y = x^2 - 1 between x=-2$ and x=3.', '["$137/6$", "$55/2$", "$-125/6$", "$125/6$"]'::jsonb, 3, 'Between $x=-2$ and $x=3$, $y=x + 5$ lies above $y=x^{2} - 1$, so the area is $\int_{-2}^{3} [(x + 5) - (x^{2} - 1)] \, dx = \int_{-2}^{3} - x^{2} + x + 6 \, dx$. An antiderivative is $F(x) = - \frac{x^{3}}{3} + \frac{x^{2}}{2} + 6 x$, so the area is $F(3) - F(-2) = \frac{3 \left(36 + 3 \cdot 3 - 2 \cdot 3^{2}\right)}{6} - (\frac{\left(-2\right) \left(36 + 3 \left(-2\right) - 2 \left(-2\right)^{2}\right)}{6}) = \frac{125}{6}$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the volume of the solid formed by revolving $y = x$ about the x-axis from x=0 to x=4.', '["$128\\pi/3$", "$-64\\pi/3$", "$8\\pi$", "$64\\pi/3$"]'::jsonb, 3, '$V = \pi \int_{0}^{4} [x]^2 \, dx = \pi \int_{0}^{4} x^{2} \, dx$. An antiderivative of the integrand is $F(x) = \frac{x^{3}}{3}$, so $V = \pi \left[F(4) - F(0)\right] = \pi \left[\frac{4^{3}}{3} - \left(\frac{0^{3}}{3}\right)\right] = \frac{64 \pi}{3}$.', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the volume of the solid formed by revolving $y = \sqrt{x}$ about the x-axis from x=0 to x=4.', '["$16\\pi$", "$8\\pi$", "$16\\pi/3$", "$-8\\pi$"]'::jsonb, 1, '$V = \pi \int_{0}^{4} [\sqrt{x}]^2 \, dx = \pi \int_{0}^{4} x \, dx$. An antiderivative of the integrand is $F(x) = \frac{x^{2}}{2}$, so $V = \pi \left[F(4) - F(0)\right] = \pi \left[\frac{4^{2}}{2} - \left(\frac{0^{2}}{2}\right)\right] = 8 \pi$.', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the volume of the solid formed by revolving $y = 2$ about the x-axis from x=0 to x=3.', '["$12\\pi$", "$24\\pi$", "$-12\\pi$", "$6\\pi$"]'::jsonb, 0, '$V = \pi \int_{0}^{3} [2]^2 \, dx = \pi \int_{0}^{3} 4 \, dx$. An antiderivative of the integrand is $F(x) = 4 x$, so $V = \pi \left[F(3) - F(0)\right] = \pi \left[4 \cdot 3 - \left(4 \cdot 0\right)\right] = 12 \pi$.', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the volume of the solid formed by revolving $y = x^2$ about the x-axis from x=0 to x=1.', '["$\\pi/3$", "$-\\pi/5$", "$2\\pi/5$", "$\\pi/5$"]'::jsonb, 3, '$V = \pi \int_{0}^{1} [x^{2}]^2 \, dx = \pi \int_{0}^{1} x^{4} \, dx$. An antiderivative of the integrand is $F(x) = \frac{x^{5}}{5}$, so $V = \pi \left[F(1) - F(0)\right] = \pi \left[\frac{1^{5}}{5} - \left(\frac{0^{5}}{5}\right)\right] = \frac{\pi}{5}$.', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \ln(3x^2 + 5)$.', '["$-6x/(3x^2 + 5)$", "$1/(3x^2 + 5)$", "$6x/(3x^2 + 5)$", "$6x$"]'::jsonb, 2, 'By the Chain Rule, $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$. With $u = 3 x^{2} + 5$, $u'' = 6 x$, giving $f''(x) = \dfrac{6 x}{3 x^{2} + 5} = \frac{6 x}{3 x^{2} + 5}$.', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \ln(\cos(x))$.', '["$1/\\cos(x)$", "$-\\sin(x)$", "$\\tan(x)$", "$-\\tan(x)$"]'::jsonb, 3, 'By the Chain Rule, $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$. With $u = \cos{\left(x \right)}$, $u'' = - \sin{\left(x \right)}$, giving $f''(x) = \dfrac{- \sin{\left(x \right)}}{\cos{\left(x \right)}} = - \tan{\left(x \right)}$.', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \ln(x^3 - 2)$.', '["$1/(x^3 - 2)$", "$3x^2/(x^3 - 2)$", "$-3x^2/(x^3 - 2)$", "$3x^2$"]'::jsonb, 1, 'By the Chain Rule, $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$. With $u = x^{3} - 2$, $u'' = 3 x^{2}$, giving $f''(x) = \dfrac{3 x^{2}}{x^{3} - 2} = \frac{3 x^{2}}{x^{3} - 2}$.', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \ln(5x - 1)$.', '["$-5/(5x - 1)$", "$5$", "$5/(5x - 1)$", "$1/(5x - 1)$"]'::jsonb, 2, 'By the Chain Rule, $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$. With $u = 5 x - 1$, $u'' = 5$, giving $f''(x) = \dfrac{5}{5 x - 1} = \frac{5}{5 x - 1}$.', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = e^{4x}$.', '["$-4e^{4x}$", "$4e^{4x}$", "$e^{4x}$", "$4$"]'::jsonb, 1, 'By the Chain Rule, $\dfrac{d}{dx}[e^u] = e^u \cdot u''$. With $u = 4 x$, $u'' = 4$, giving $f''(x) = e^{4 x} \cdot 4 = 4 e^{4 x}$.', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = e^{x^2}$.', '["-2xe^(x^2)", "$2x$", "2xe^(x^2)", "$e^{x^2}$"]'::jsonb, 2, 'By the Chain Rule, $\dfrac{d}{dx}[e^u] = e^u \cdot u''$. With $u = x^{2}$, $u'' = 2 x$, giving $f''(x) = e^{x^{2}} \cdot 2 x = 2 x e^{x^{2}}$.', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = e^{\sin(x)}$.', '["$e^{\\sin(x)}$", "$\\cos(x)$", "$-e^{\\sin(x)}\\cos(x)$", "$e^{\\sin(x)}\\cos(x)$"]'::jsonb, 3, 'By the Chain Rule, $\dfrac{d}{dx}[e^u] = e^u \cdot u''$. With $u = \sin{\left(x \right)}$, $u'' = \cos{\left(x \right)}$, giving $f''(x) = e^{\sin{\left(x \right)}} \cdot \cos{\left(x \right)} = e^{\sin{\left(x \right)}} \cos{\left(x \right)}$.', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = e^{2x - 1}$.', '["$2$", "$2e^{2x - 1}$", "$-2e^{2x - 1}$", "$e^{2x - 1}$"]'::jsonb, 1, 'By the Chain Rule, $\dfrac{d}{dx}[e^u] = e^u \cdot u''$. With $u = 2 x - 1$, $u'' = 2$, giving $f''(x) = e^{2 x - 1} \cdot 2 = 2 e^{2 x - 1}$.', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = a \sin(x)$.', '["$-1/\\sqrt{1 - x^2}$", "$1/(x^2 + 1)$", "$1/\\sqrt{1 - x^2}$", "$\\sqrt{1 - x^2}$"]'::jsonb, 2, 'Using the standard derivative formula for inverse trigonometric functions: $\dfrac{d}{dx}[\arcsin(x)] = \frac{1}{\sqrt{1 - x^{2}}}$.', 'Inverse Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = a \cos(x)$.', '["$1/\\sqrt{1 - x^2}$", "$\\sqrt{1 - x^2}$", "$1/(x^2 + 1)$", "$-1/\\sqrt{1 - x^2}$"]'::jsonb, 3, 'Using the standard derivative formula for inverse trigonometric functions: $\dfrac{d}{dx}[\arccos(x)] = - \frac{1}{\sqrt{1 - x^{2}}}$.', 'Inverse Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = a \tan(x)$.', '["$\\sqrt{1 - x^2}$", "$1/(x^2 + 1)$", "$-1/(x^2 + 1)$", "$1/\\sqrt{1 - x^2}$"]'::jsonb, 1, 'Using the standard derivative formula for inverse trigonometric functions: $\dfrac{d}{dx}[\arctan(x)] = \frac{1}{x^{2} + 1}$.', 'Inverse Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = \ln(x^2 + 1)$, find $f''(2)$.', '["$4/3$", "$2/5$", "$1/5$", "$4/5$"]'::jsonb, 3, '$f''(x) = \dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$ with $u = x^{2} + 1$: $f''(x) = \frac{2 x}{x^{2} + 1}$. At $x=2$: $f''(2) = \frac{2 \cdot 2}{2^{2} + 1} = \frac{4}{5}$.', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = e^{3x}$, find $f''(0)$.', '["$e^{3}$", "$0$", "$3$", "$1$"]'::jsonb, 2, '$f''(x) = \dfrac{d}{dx}[e^u] = e^u \cdot u''$ with $u = 3 x$: $f''(x) = 3 e^{3 x}$. At $x=0$: $f''(0) = 3 e^{3 \cdot 0} = 3$.', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int 1/x \, dx$.', '["$1/x^2 + C$", "$-1/x^2 + C$", "$ln|x| + C$", "$x \\cdot \\ln(x) + C$"]'::jsonb, 2, 'With $u = x$, $du = 1 \, dx$. $\int \dfrac{1}{x} \, dx = \int \dfrac{1}{u} \, du = \ln|u| + C = \ln|x| + C$.', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int 2/(2x+1) \, dx$.', '["$2ln|2x+1| + C$", "$ln|x| + C$", "$(1/2)ln|2x+1| + C$", "$ln|2x+1| + C$"]'::jsonb, 3, 'With $u = 2 x + 1$, $du = 2 \, dx$. $\int \dfrac{2}{2 x + 1} \, dx = \int \dfrac{1}{u} \, du = \ln|u| + C = \ln|2 x + 1| + C$.', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int e^{5x} \, dx$.', '["$(1/5)e^{5x} + C$", "$5e^{5x} + C$", "$e^{5x} + C$", "$e^{5x}/x + C$"]'::jsonb, 0, 'With $u = 5 x$, $du = 5 \, dx$. $\int e^{5 x} \, dx = \dfrac{1}{5} \int e^u \, du = \dfrac{1}{5} e^u + C = \dfrac{1}{5} e^{5 x} + C$.', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int (3x + 5)^4 \, dx$.', '["$81x^5/5 + 135x^4 + 450x^3 + 750x^2 + 625x + C$", "$243x^5/5 + 405x^4 + 1350x^3 + 2250x^2 + 1875x + C$", "$-81x^5/5 - 135x^4 - 450x^3 - 750x^2 - 625x + C$", "$324x^3 + 1620x^2 + 2700x + 1500 + C$"]'::jsonb, 0, 'Let $u = 3 x + 5$, so $du = 3 \, dx$. $\int \left(3 x + 5\right)^{4} \, dx = \dfrac{1}{3} \int u^{4} \, du = \dfrac{1}{3} \cdot \dfrac{u^{5}}{5} + C$. Substituting back $u = 3 x + 5$ and expanding: $\int \left(3 x + 5\right)^{4} \, dx = \frac{81 x^{5}}{5} + 135 x^{4} + 450 x^{3} + 750 x^{2} + 625 x + C$.', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int \cos(2x + 1) \, dx$.', '["$-\\sin(2x + 1)/2 + C$", "$3 \\sin(2x + 1)/2 + C$", "$\\sin(2x + 1)/2 + C$", "$-2 \\sin(2x + 1) + C$"]'::jsonb, 2, 'Let $u = 2 x + 1$, so $du = 2 \, dx$. $\int \cos(2 x + 1) \, dx = \dfrac{1}{2} \int \cos(u) \, du = \dfrac{1}{2} \sin(u) + C$. Substituting back $u = 2 x + 1$: $\int \cos(2 x + 1) \, dx = \frac{\sin{\left(2 x + 1 \right)}}{2} + C$.', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int (4 - 3x)^3 \, dx$.', '["$-81x^2 + 216x - 144 + C$", "$-81x^4/4 + 108x^3 - 216x^2 + 192x + C$", "$27x^4/4 - 36x^3 + 72x^2 - 64x + C$", "$-27x^4/4 + 36x^3 - 72x^2 + 64x + C$"]'::jsonb, 3, 'Let $u = 4 - 3 x$, so $du = -3 \, dx$. $\int \left(4 - 3 x\right)^{3} \, dx = \dfrac{1}{-3} \int u^{3} \, du = \dfrac{1}{-3} \cdot \dfrac{u^{4}}{4} + C$. Substituting back $u = 4 - 3 x$ and expanding: $\int \left(4 - 3 x\right)^{3} \, dx = - \frac{27 x^{4}}{4} + 36 x^{3} - 72 x^{2} + 64 x + C$.', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int \sin(5x) \, dx$.', '["$-3 \\cos(5x)/5 + C$", "$-\\cos(5x)/5 + C$", "$\\cos(5x)/5 + C$", "$5 \\cos(5x) + C$"]'::jsonb, 1, 'Using an appropriate substitution for the inner expression, $\int \sin{\left(5 x \right)} \, dx = - \frac{\cos{\left(5 x \right)}}{5} + C$.', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{0}^{1} 2x(x^2 + 1)^3 \, dx$.', '["$15/4$", "$15/2$", "$-15/4$", "$19/4$"]'::jsonb, 0, 'Using substitution, an antiderivative is $F(x) = \frac{x^{8}}{4} + x^{6} + \frac{3 x^{4}}{2} + x^{2}$. Evaluating from $x=0$ to $x=1$: $F(1) - F(0) = \frac{15}{4} - 0 = \frac{15}{4}$.', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{0}^{pi/2} \sin(x)^2 \cos(x) \, dx$.', '["$2/3$", "$1/3$", "$-1/3$", "$4/3$"]'::jsonb, 1, 'Using substitution, an antiderivative is $F(x) = \frac{\sin^{3}{\left(x \right)}}{3}$. Evaluating from $x=0$ to $x=\frac{\pi}{2}$: $F(\frac{\pi}{2}) - F(0) = \frac{1}{3} - 0 = \frac{1}{3}$.', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{0}^{2} x/(x^2 + 4) \, dx$.', '["$3 \\log(2)/2$", "$-\\ln(2)/2$", "$\\ln(2)/2$", "$\\ln(2)$"]'::jsonb, 2, 'Using substitution, an antiderivative is $F(x) = \frac{\log{\left(x^{2} + 4 \right)}}{2}$. Evaluating from $x=0$ to $x=2$: $F(2) - F(0) = \log{\left(2 \sqrt{2} \right)} - \log{\left(2 \right)} = \log{\left(\sqrt{2} \right)}$.', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int xe^{x} \, dx$.', '["xe^(x) + C", "$(1 - x)e^{x} + C$", "$(x - 1)e^{x} + C$", "$x^2e^{x}/2 + C$"]'::jsonb, 2, 'With $u = x$ and $dv = e^{x} \, dx$: $du = dx$ and $v = e^{x}$. Integration by parts, $\int u \, dv = uv - \int v \, du$, gives $\int x e^{x} \, dx = xe^{x} - \int e^{x} \, dx = \left(x - 1\right) e^{x} + C$.', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int x \sin(x) \, dx$.', '["$-x \\cos(x) + \\sin(x) + C$", "$-x \\cos(x) + C$", "$-x^2 \\cos(x)/2 + C$", "$x \\cos(x) - \\sin(x) + C$"]'::jsonb, 0, 'With $u = x$ and $dv = \sin{\left(x \right)} \, dx$: $du = dx$ and $v = - \cos{\left(x \right)}$. Integration by parts, $\int u \, dv = uv - \int v \, du$, gives $\int x \sin{\left(x \right)} \, dx = x- \cos{\left(x \right)} - \int - \cos{\left(x \right)} \, dx = - x \cos{\left(x \right)} + \sin{\left(x \right)} + C$.', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int x \cos(x) \, dx$.', '["$-x \\sin(x) - \\cos(x) + C$", "$x^2 \\sin(x)/2 + C$", "$x \\sin(x) + C$", "$x \\sin(x) + \\cos(x) + C$"]'::jsonb, 3, 'With $u = x$ and $dv = \cos{\left(x \right)} \, dx$: $du = dx$ and $v = \sin{\left(x \right)}$. Integration by parts, $\int u \, dv = uv - \int v \, du$, gives $\int x \cos{\left(x \right)} \, dx = x\sin{\left(x \right)} - \int \sin{\left(x \right)} \, dx = x \sin{\left(x \right)} + \cos{\left(x \right)} + C$.', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\int_{0}^{1} x \cdot e^x \, dx$.', '["$-1 + E$", "E", "$0$", "$1$"]'::jsonb, 3, 'Using integration by parts with $u = x$, $dv = e^{x} \, dx$: $v = e^{x}$, so $\int x \, e^{x} \, dx = xe^{x} - \int e^{x} \, dx = \left(x - 1\right) e^{x} + C$. Evaluating from $0$ to $1$: $(\left(-1 + 1\right) e^{1}) - (\left(-1 + 0\right) e^{0}) = 0 - -1 = 1$.', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\int \tan(x) \, dx$.', '["$ln|\\sec(x)| + C$", "$ln|\\cos(x)| + C$", "$\\sec(x)\\tan(x) + C$", "$ln|\\sin(x)| + C$"]'::jsonb, 0, 'Writing $\tan(x) = \sin(x)/\cos(x)$ and substituting $v = \cos(x)$ (so $dv = -\sin(x) \, dx$) gives $\int \tan(x) \, dx = -\ln|\cos(x)| + C$, which is the same as $\ln|\sec(x)| + C$ (since $-\ln|\cos(x)| = \ln|\cos(x)|^{-1} = \ln|\sec(x)|$).', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate the limit, as h approaches 0, of [f(x+h) - f(x)]/h for $f(x) = x^2$.', '["$2x$", "$x^2$", "$2$", "x"]'::jsonb, 0, 'By definition, $f''(x) = \lim_{h \to 0} \dfrac{f(x+h) - f(x)}{h}$. Here $f(x+h) = (x+h)^2 = x^2 + 2xh + h^2$, so $\dfrac{f(x+h)-f(x)}{h} = \dfrac{2xh + h^2}{h} = 2x + h$. Letting $h \to 0$ gives $f''(x) = 2x$.', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate the limit, as h approaches 0, of [f(x+h) - f(x)]/h for $f(x) = 3x + 2$.', '["$3x$", "$2$", "$3$", "$0$"]'::jsonb, 2, '$f(x+h) = 3(x+h) + 2 = 3x + 3h + 2$, so $\dfrac{f(x+h) - f(x)}{h} = \dfrac{3h}{h} = 3$ for every $h \neq 0$. Letting $h \to 0$, $f''(x) = 3$ -- a straight line''s slope never changes.', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^2 + 2x$, evaluate the limit, as h approaches 0, of [f(1+h) - $f(1)$$]/h$.', '["$3$", "$4$", "$2$", "$1$"]'::jsonb, 1, '$f(x+h) - f(x) = (x+h)^{2} + 2(x+h) - x^{2} - 2x = 2xh + h^{2} + 2h$, so $\dfrac{f(x+h)-f(x)}{h} = 2x + h + 2$. Letting $h \to 0$ gives $f''(x) = 2x + 2$, so $f''(1) = 2(1) + 2 = 4$.', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate the limit, as h approaches 0, of [f(x+h) - f(x)]/h for $f(x) = 1/x$, where x is not 0.', '["$1/x^2$", "$-1/x^2$", "$-1/x$", "$1/x$"]'::jsonb, 1, '$\dfrac{f(x+h)-f(x)}{h} = \dfrac{1}{h}\left(\dfrac{1}{x+h} - \dfrac{1}{x}\right) = \dfrac{1}{h} \cdot \dfrac{x - (x+h)}{x(x+h)} = \dfrac{-h}{h \cdot x(x+h)} = \dfrac{-1}{x(x+h)}$. Letting $h \to 0$ gives $f''(x) = -\dfrac{1}{x^{2}}$.', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^2 - 3x$, evaluate the limit, as h approaches 0, of [f(2+h) - $f(2)$$]/h$.', '["$-1$", "$0$", "$1$", "$4$"]'::jsonb, 2, '$f(x+h) - f(x) = (x+h)^{2} - 3(x+h) - x^{2} + 3x = 2xh + h^{2} - 3h$, so $\dfrac{f(x+h)-f(x)}{h} = 2x + h - 3$. Letting $h \to 0$ gives $f''(x) = 2x - 3$, so $f''(2) = 2(2) - 3 = 1$.', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the line tangent to the curve $y = x^3$ at the point (1,1).', '["$1$", "$2$", "$3$", "$9$"]'::jsonb, 2, 'The slope of the tangent at $x=x_0$ is $y''(x_0)$. Here $y'' = 3x^{2}$, so at $x_0=1$, the slope is $y''(1) = 3(1)^{2} = 3$.', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the line tangent to the curve $y = 3x^2 + 1$ at the point (1,4).', '["$y = 6x - 2$", "$y = 3x + 1$", "$y = 6x + 4$", "$y = 2x + 2$"]'::jsonb, 0, '$y'' = 6x$, so the slope at $(1,4)$ is $y''(1) = 6$. Using the point-slope form $y - y_0 = m(x - x_0)$ with $m=6$, $(x_0,y_0)=(1,4)$: $y - 4 = 6(x - 1)$, which simplifies to $y = 6x - 2$.', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the line normal to the curve $y = x^3 + 1$ at the point (-1,0).', '["$y = 3x + 3$", "$x + 3y = -1$", "$y = -3x - 3$", "$3x + y = -3$"]'::jsonb, 1, '$y'' = 3x^{2}$, so the slope of the tangent at $(-1,0)$ is $y''(-1) = 3$. The normal is perpendicular to the tangent, so its slope is $-\dfrac{1}{3}$. Using point-slope form: $y - 0 = -\dfrac{1}{3}(x - (-1))$, i.e. $3y = -(x+1)$, which rearranges to $x + 3y = -1$.', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent to the curve $y = x^2 - 4x + 3$ at the point (3,0).', '["$-2$", "$0$", "$2$", "$3$"]'::jsonb, 2, '$y'' = 2x - 4$, so at $x=3$ the slope is $y''(3) = 2(3) - 4 = 2$.', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the line normal to the curve $y = 1/x$ at the point (2, 1/2).', '["$y = 4x - 15/2$", "$y = -x/4 + 1$", "$x + 4y = 4$", "$y = 4x - 7$"]'::jsonb, 0, '$y'' = -\dfrac{1}{x^{2}}$, so the tangent''s slope at $(2,\tfrac{1}{2})$ is $y''(2) = -\dfrac{1}{4}$. The normal''s slope is the negative reciprocal, $4$. Point-slope form gives $y - \dfrac{1}{2} = 4(x-2)$, which simplifies to $y = 4x - \dfrac{15}{2}$.', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The displacement of a particle moving along a line is s(t) = t^3 - 6t^2 + 9t. Find its velocity at t = 2.', '["$-3$", "$0$", "$3$", "$6$"]'::jsonb, 0, 'Velocity is $v(t) = s''(t) = 3t^{2} - 12t + 9$. At $t=2$: $v(2) = 3(2)^{2} - 12(2) + 9 = 12 - 24 + 9 = -3$.', 'Velocity and Acceleration', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For the displacement s(t) = t^3 - 6t^2 + 9t, find the acceleration at t = 1.', '["$-6$", "$0$", "$6$", "$12$"]'::jsonb, 0, 'Acceleration is $a(t) = v''(t) = s''''(t) = 6t - 12$. At $t=1$: $a(1) = 6(1) - 12 = -6$.', 'Velocity and Acceleration', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'A ball thrown upward has height s(t) = 16t - t^2 (metres, t in seconds). At what time does the ball reach its maximum height (v = 0)?', '["$t = 4$", "$t = 8$", "$t = 16$", "$t = 32$"]'::jsonb, 1, 'Velocity is $v(t) = s''(t) = 16 - 2t$. The ball is at its highest point when $v(t)=0$: $16 - 2t = 0 \Rightarrow t = 8$.', 'Velocity and Acceleration', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'An object''s position is s(t) = t^2 - 4t + 3. At what time t is the object momentarily at rest (v = 0)?', '["$t = 1$", "$t = 2$", "$t = 3$", "$t = 4$"]'::jsonb, 1, '$v(t) = s''(t) = 2t - 4$. Setting $v(t) = 0$: $2t - 4 = 0 \Rightarrow t = 2$.', 'Velocity and Acceleration', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The velocity of a particle is v(t) = 3t^2 - 6t. Find its acceleration at t = 2.', '["$0$", "$6$", "$12$", "$18$"]'::jsonb, 1, 'Acceleration is $a(t) = v''(t) = 6t - 6$. At $t=2$: $a(2) = 6(2) - 6 = 6$.', 'Velocity and Acceleration', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the second derivative f''''(x) for $f(x) = x^4 - 3x^2$.', '["$4x^3 - 6x$", "$12x^2 - 6$", "$12x^2 - 3$", "$24x$"]'::jsonb, 1, '$f''(x) = 4x^{3} - 6x$. Differentiating again, $f''''(x) = 12x^{2} - 6$.', 'Higher Order Derivatives', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the third derivative f''''''(x) for $f(x) = \sin(x)$.', '["$-\\cos(x)$", "$\\cos(x)$", "$-\\sin(x)$", "$\\sin(x)$"]'::jsonb, 0, '$f''(x) = \cos(x)$, $f''''(x) = -\sin(x)$, and differentiating once more, $f''''''(x) = -\cos(x)$.', 'Higher Order Derivatives', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $f''''(1)$ for $f(x) = x^3 - 2x$.', '["$1$", "$2$", "$6$", "$-2$"]'::jsonb, 2, '$f''(x) = 3x^{2} - 2$, so $f''''(x) = 6x$. At $x=1$: $f''''(1) = 6(1) = 6$.', 'Higher Order Derivatives', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the second derivative of $f(x) = e^{2x}$.', '["$2e^{2x}$", "$4e^{2x}$", "$e^{2x}$", "$4e^x$"]'::jsonb, 1, '$f''(x) = 2 e^{2x}$ by the chain rule. Differentiating again, $f''''(x) = 2 \cdot 2 e^{2x} = 4 e^{2x}$.', 'Higher Order Derivatives', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the second derivative of $f(x) = \ln(x)$, for $x > 0.$', '["$1/x^2$", "$-1/x^2$", "$-1/x$", "$1/x$"]'::jsonb, 1, '$f''(x) = \dfrac{1}{x}$. Differentiating $x^{-1}$ again gives $f''''(x) = -x^{-2} = -\dfrac{1}{x^{2}}$.', 'Higher Order Derivatives', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^3 - 3x$, determine the nature of the critical point at x = -1.', '["relative maximum", "relative minimum", "point of inflection", "not a critical point"]'::jsonb, 0, '$f''(x) = 3x^{2} - 3 = 3(x-1)(x+1)$, so the critical points are $x=-1$ and $x=1$. For $x$ slightly less than $-1$, $f''(x) > 0$ (increasing); for $x$ slightly greater than $-1$, $f''(x) < 0$ (decreasing). Since $f''$ changes from positive to negative, $x=-1$ is a relative maximum.', 'Extrema of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = 2x^3 - 3x^2 + 2$, classify the critical point at x = 1.', '["relative minimum", "relative maximum", "neither ($f''''(1)$ $= 0)$", "not a critical point"]'::jsonb, 0, '$f''(x) = 6x^{2} - 6x = 6x(x-1)$, so $x=1$ is a critical point. $f''''(x) = 12x - 6$, so $f''''(1) = 12(1) - 6 = 6 > 0$. Since $f''''(1) > 0$, the second derivative test says $x=1$ is a relative minimum.', 'Extrema of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the absolute minimum value of $f(x) = x^2 - 4x + 3$ on the closed interval [0,5].', '["$-1$", "$0$", "$3$", "$8$"]'::jsonb, 0, '$f''(x) = 2x - 4 = 0$ at $x=2$, an interior critical point. Checking $f$ at the critical point and both endpoints: $f(0)=3$, $f(2) = 4-8+3=-1$, $f(5) = 25-20+3=8$. The smallest of these is $f(2) = -1$, so the absolute minimum on $[0,5]$ is $-1$.', 'Extrema of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^3 - 3x^2$, classify the critical point at x = 2.', '["relative minimum", "relative maximum", "neither", "cannot be determined"]'::jsonb, 0, '$f''(x) = 3x^{2} - 6x = 3x(x-2)$, so $x=0$ and $x=2$ are critical points. $f''''(x) = 6x - 6$, so $f''''(2) = 6(2) - 6 = 6 > 0$, meaning $x=2$ is a relative minimum by the second derivative test.', 'Extrema of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^4 - 4x^2$, classify the critical point at x = 0.', '["relative maximum", "relative minimum", "neither a maximum nor a minimum", "not a critical point"]'::jsonb, 0, '$f''(x) = 4x^{3} - 8x = 4x(x^{2}-2)$, so the critical points are $x=0, \sqrt{2}, -\sqrt{2}$. $f''''(x) = 12x^{2} - 8$, so $f''''(0) = -8 < 0$. Since $f''''(0) < 0$, the second derivative test says $x=0$ is a relative maximum.', 'Extrema of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'A curve is symmetric about the y-axis if replacing x by -x leaves its equation unchanged. Determine the symmetry of $y = x^4 - 3x^2 + 1$.', '["symmetric about the y-axis", "symmetric about the x-axis", "symmetric about the origin", "no symmetry"]'::jsonb, 0, 'Replace $x$ by $-x$: $(-x)^{4} - 3(-x)^{2} + 1 = x^{4} - 3x^{2} + 1$, which is identical to the original equation. Since the equation is unchanged when $x$ is replaced by $-x$, the curve is symmetric about the y-axis.', 'Symmetry and Intercepts of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'A curve is symmetric about the origin if replacing both x by -x and y by -y leaves its equation unchanged. Determine the symmetry of xy = 4.', '["symmetric about the origin", "symmetric about the y-axis", "symmetric about the x-axis", "no symmetry"]'::jsonb, 0, 'Replace $x$ by $-x$ and $y$ by $-y$: $(-x)(-y) = xy$, which equals the original left-hand side. Since the equation $xy=4$ is unchanged under this replacement, the curve is symmetric about the origin.', 'Symmetry and Intercepts of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the x-intercepts of the graph of $y = x^2 - 5x + 6$.', '["x = 2 and x = 3", "x = -2 and x = -3", "x = 1 and x = 6", "x = 0 and x = 6"]'::jsonb, 0, 'The x-intercepts satisfy $y=0$: $x^{2} - 5x + 6 = 0$, which factors as $(x-2)(x-3) = 0$, giving $x=2$ or $x=3$.', 'Symmetry and Intercepts of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'A curve $y = f(x)$ is symmetric about the origin if f(-x) = -f(x) (an odd function). Determine the symmetry of $y = x^3 - x$.', '["symmetric about the origin", "symmetric about the y-axis", "symmetric about the x-axis", "no symmetry"]'::jsonb, 0, 'Replace $x$ by $-x$: $(-x)^{3} - (-x) = -x^{3} + x = -(x^{3}-x)$. Since this equals the negative of the original expression, i.e. $f(-x) = -f(x)$, the function is odd and its graph is symmetric about the origin.', 'Symmetry and Intercepts of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the y-intercepts of the graph of x^2 + y^2 = 9.', '["$y = -3$ and $y = 3$", "$y = -9$ and $y = 9$", "$y = 0$ only", "$y = 3$ only"]'::jsonb, 0, 'Set $x=0$: $0 + y^{2} = 9$, so $y^{2} = 9$, giving $y = 3$ or $y = -3$.', 'Symmetry and Intercepts of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the horizontal asymptote of the graph of $y = (x - 1)/(x + 2)$.', '["$y = 1$", "$y = -1$", "$y = 0$", "$y = 2$"]'::jsonb, 0, 'For a rational function, the horizontal asymptote is $\lim_{x \to \infty} \dfrac{x-1}{x+2}$. Dividing numerator and denominator by $x$: $\dfrac{1 - 1/x}{1 + 2/x} \to \dfrac{1}{1} = 1$ as $x \to \infty$. So $y=1$ is the horizontal asymptote.', 'Asymptotes of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the horizontal asymptote of the graph of $y = (2x^2 + 1)/(x^2 - 4)$.', '["$y = 2$", "$y = 1$", "$y = -4$", "$y = 0$"]'::jsonb, 0, 'Since the numerator and denominator have the same degree, the horizontal asymptote is the ratio of leading coefficients: $y = \dfrac{2}{1} = 2$, confirmed by $\lim_{x \to \infty} \dfrac{2x^{2}+1}{x^{2}-4} = 2$.', 'Asymptotes of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the vertical asymptotes of the graph of $y = 1/(x^2 - 9)$.', '["x = 3 and x = -3", "x = 9 and x = -9", "$x = 0$", "there are none"]'::jsonb, 0, 'Vertical asymptotes of a proper rational function occur where the denominator is zero (and the numerator is not): $x^{2} - 9 = 0 \Rightarrow x = 3$ or $x=-3$.', 'Asymptotes of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the horizontal asymptote of the graph of $y = (3x + 1)/(x - 5)$.', '["$y = 3$", "$y = -1/5$", "$y = 5$", "$y = 1$"]'::jsonb, 0, 'Dividing numerator and denominator by $x$: $\dfrac{3 + 1/x}{1 - 5/x} \to \dfrac{3}{1} = 3$ as $x \to \infty$. So $y=3$ is the horizontal asymptote.', 'Asymptotes of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the vertical asymptote of the graph of $y = (x + 1)/(x - 3)$.', '["$x = 3$", "$x = -1$", "$x = -3$", "$y = 1$"]'::jsonb, 0, 'The denominator vanishes at $x = 3$ (and the numerator, $x+1=4$, does not), so $x = 3$ is a vertical asymptote.', 'Asymptotes of a Curve', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\lim_{x \to 0^+} [|x|/x]$, the right-hand limit as x approaches 0.', '["$1$", "$-1$", "$0$", "the limit does not exist"]'::jsonb, 0, 'For $x > 0$, $|x| = x$, so $\dfrac{|x|}{x} = \dfrac{x}{x} = 1$ for every $x>0$. Hence $\lim_{x \to 0^+} \dfrac{|x|}{x} = 1$.', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\lim_{x \to 0^-} [|x|/x]$, the left-hand limit as x approaches 0.', '["$-1$", "$1$", "$0$", "the limit does not exist"]'::jsonb, 0, 'For $x < 0$, $|x| = -x$, so $\dfrac{|x|}{x} = \dfrac{-x}{x} = -1$ for every $x<0$. Hence $\lim_{x \to 0^-} \dfrac{|x|}{x} = -1$.', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find $\lim_{x \to 3^+} [(x-3)/|x-3|]$.', '["$1$", "$-1$", "$0$", "does not exist"]'::jsonb, 0, 'For $x > 3$, $x - 3 > 0$ so $|x-3| = x-3$, giving $\dfrac{x-3}{|x-3|} = 1$ for every $x$ just above $3$. Hence $\lim_{x \to 3^+} \dfrac{x-3}{|x-3|} = 1$.', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'A function f is defined by $f(x) = x+1$ for $x<1$ and $f(x) = 4-x$ for x greater than or equal to 1. Find $\lim_{x \to 1^-} [f(x)]$.', '["$2$", "$3$", "$1$", "$4$"]'::jsonb, 0, 'For $x < 1$, $f(x) = x+1$, so the left-hand limit uses this branch: $\lim_{x \to 1^-} (x+1) = 1 + 1 = 2$.', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'A function f is defined by $f(x) = x+1$ for $x<1$ and $f(x) = 4-x$ for x greater than or equal to 1. Find $\lim_{x \to 1^+} [f(x)]$.', '["$3$", "$2$", "$1$", "$4$"]'::jsonb, 0, 'For $x \geq 1$, $f(x) = 4-x$, so the right-hand limit uses this branch: $\lim_{x \to 1^+} (4-x) = 4 - 1 = 3$.', 'One-sided Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 0} [1/x^2]$.', '["infinity", "$0$", "$1$", "the limit does not exist and is not infinite"]'::jsonb, 0, 'As $x \to 0$ from either side, $x^{2} \to 0^{+}$ (always positive), so $\dfrac{1}{x^{2}}$ grows without bound. Hence $\lim_{x \to 0} \dfrac{1}{x^{2}} = \infty$.', 'Infinite Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 2^+} [1/(x-2)]$.', '["infinity", "negative infinity", "$0$", "$1$"]'::jsonb, 0, 'As $x \to 2^{+}$, $x-2 \to 0^{+}$ (a small positive number), so $\dfrac{1}{x-2}$ grows without bound through positive values. Hence $\lim_{x \to 2^+} \dfrac{1}{x-2} = \infty$.', 'Infinite Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 2^-} [1/(x-2)]$.', '["negative infinity", "infinity", "$0$", "$-1$"]'::jsonb, 0, 'As $x \to 2^{-}$, $x-2 \to 0^{-}$ (a small negative number), so $\dfrac{1}{x-2}$ decreases without bound through negative values. Hence $\lim_{x \to 2^-} \dfrac{1}{x-2} = -\infty$.', 'Infinite Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 3} [1/(x-3)^2]$.', '["infinity", "negative infinity", "$0$", "does not exist and is not infinite"]'::jsonb, 0, 'As $x \to 3$ from either side, $(x-3)^{2} \to 0^{+}$ (a square is never negative), so $\dfrac{1}{(x-3)^{2}}$ grows without bound through positive values. Hence $\lim_{x \to 3} \dfrac{1}{(x-3)^{2}} = \infty$.', 'Infinite Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 0} [-1/x^4]$.', '["negative infinity", "infinity", "$0$", "$-1$"]'::jsonb, 0, 'As $x \to 0$, $x^{4} \to 0^{+}$, so $\dfrac{1}{x^{4}} \to \infty$ and therefore $-\dfrac{1}{x^{4}} \to -\infty$. Hence $\lim_{x \to 0} \left(-\dfrac{1}{x^{4}}\right) = -\infty$.', 'Infinite Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The function $f(x) = (x^2 - 4)/(x - 2)$ is undefined at x = 2. Classify the discontinuity at x = 2.', '["removable discontinuity", "jump discontinuity", "essential (infinite) discontinuity", "f is actually continuous at x=2"]'::jsonb, 0, '$f(2)$ is undefined (division by zero), but $\lim_{x \to 2} \dfrac{x^{2}-4}{x-2} = \lim_{x \to 2} \dfrac{(x-2)(x+2)}{x-2} = \lim_{x \to 2}(x+2) = 4$, which exists. Since the limit exists even though $f(2)$ does not, the discontinuity can be removed by defining $f(2)=4$ -- this is a removable discontinuity.', 'Types of Discontinuity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'A function f is defined by $f(x) = x+1$ for $x<1$ and $f(x) = 4-x$ for x greater than or equal to 1. Classify the discontinuity of f at x = 1.', '["jump discontinuity", "removable discontinuity", "f is continuous at x=1", "essential discontinuity that is not a jump"]'::jsonb, 0, '$\lim_{x \to 1^-} f(x) = \lim_{x \to 1^-}(x+1) = 2$ and $\lim_{x \to 1^+} f(x) = \lim_{x \to 1^+}(4-x) = 3$. Both one-sided limits exist but are unequal ($2 \neq 3$), so $\lim_{x \to 1} f(x)$ does not exist. Since both one-sided limits exist but differ, this is a jump discontinuity.', 'Types of Discontinuity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Classify the discontinuity of $f(x) = 1/x$ at x = 0.', '["essential (infinite) discontinuity", "removable discontinuity", "jump discontinuity", "f is continuous at x=0"]'::jsonb, 0, 'As $x \to 0^{+}$, $\dfrac{1}{x} \to \infty$, and as $x \to 0^{-}$, $\dfrac{1}{x} \to -\infty$. Neither one-sided limit exists as a finite number, so this cannot be patched by redefining a single point -- it is an essential (infinite) discontinuity.', 'Types of Discontinuity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Let $f(x) = (x^2 - 9)/(x - 3)$ for x not equal to 3, and $f(3)$ $= 10$. Classify the discontinuity of f at x = 3.', '["removable discontinuity", "jump discontinuity", "f is continuous at x=3", "essential discontinuity"]'::jsonb, 0, '$\lim_{x \to 3} \dfrac{x^{2}-9}{x-3} = \lim_{x \to 3}(x+3) = 6$, which exists, but the given value $f(3) = 10 \neq 6$. Since the limit exists but does not match the defined function value, this is a removable discontinuity (redefining $f(3)=6$ would make $f$ continuous there).', 'Types of Discontinuity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The greatest integer function $f(x) = [x] ($the largest integer <= x) is discontinuous at every integer. Classify the discontinuity at x = 2.', '["jump discontinuity", "removable discontinuity", "essential discontinuity that is not a jump", "f is continuous at x=2"]'::jsonb, 0, '$\lim_{x \to 2^-} [x] = 1$ (just below 2, the greatest integer is still 1) while $\lim_{x \to 2^+} [x] = 2$. Both one-sided limits exist but are unequal, so this is a jump discontinuity.', 'Types of Discontinuity', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the inverse of the function $f(x) = 2x + 3$.', '["$f^{-1}(x) = (x-3)/2$", "$f^{-1}(x) = 2x-3$", "$f^{-1}(x) = (x+3)/2$", "$f^{-1}(x) = x/2 - 3$"]'::jsonb, 0, 'Set $y = 2x+3$ and solve for $x$: $y - 3 = 2x$, so $x = \dfrac{y-3}{2}$. Swapping the roles of $x$ and $y$ gives $f^{-1}(x) = \dfrac{x-3}{2}$.', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the inverse of the function $f(x) = x^3$.', '["$f^{-1}(x) = x^{1/3}$", "$f^{-1}(x) = x^3$", "$f^{-1}(x) = 1/x^3$", "$f^{-1}(x) = 3x$"]'::jsonb, 0, 'Set $y = x^{3}$ and solve for $x$: taking the cube root of both sides, $x = y^{1/3}$. Swapping $x$ and $y$ gives $f^{-1}(x) = x^{1/3}$.', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = 5x - 2$, find $f^{-1}(8)$.', '["$2$", "$3$", "$38$", "$1$"]'::jsonb, 0, 'Set $y = 5x-2$ and solve for $x$: $x = \dfrac{y+2}{5}$, so $f^{-1}(x) = \dfrac{x+2}{5}$. Then $f^{-1}(8) = \dfrac{8+2}{5} = \dfrac{10}{5} = 2$. (Check: $f(2) = 5(2)-2 = 8$, confirming the inverse.)', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The function $f(x) = x^2$ for x >= 0 has inverse $f^{-1}(x) = \sqrt{x}$. Find $f^{-1}(9)$.', '["$3$", "$9$", "$81$", "$4.5$"]'::jsonb, 0, 'Since $f^{-1}(x) = \sqrt{x}$ for $x \geq 0$, $f^{-1}(9) = \sqrt{9} = 3$. (Check: $f(3) = 3^{2} = 9$, confirming the inverse.)', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the inverse of the function $f(x) = (x + 1)/2$.', '["$f^{-1}(x) = 2x - 1$", "$f^{-1}(x) = 2x + 1$", "$f^{-1}(x) = (x-1)/2$", "$f^{-1}(x) = x/2 - 1$"]'::jsonb, 0, 'Set $y = \dfrac{x+1}{2}$ and solve for $x$: $2y = x+1$, so $x = 2y - 1$. Swapping $x$ and $y$ gives $f^{-1}(x) = 2x - 1$.', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the volume of the solid formed by revolving about the y-axis the region under $y = x^2$ from x=0 to x=2.', '["$8\\pi$", "$16\\pi/3$", "$4\\pi$", "$32\\pi/5$"]'::jsonb, 0, 'By the shell method, revolving about the y-axis gives $V = 2\pi \int_{0}^{2} x \cdot f(x) \, dx = 2\pi \int_{0}^{2} x \cdot x^{2} \, dx = 2\pi \int_{0}^{2} x^{3} \, dx$. An antiderivative of the integrand is $F(x) = \dfrac{x^{4}}{4}$, so $V = 2\pi \left[F(2)-F(0)\right] = 2\pi \left[\dfrac{16}{4} - 0\right] = 2\pi(4) = 8\pi$.', 'The Shell Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the volume of the solid formed by revolving about the y-axis the region under $y = x$ from x=0 to x=3.', '["$18\\pi$", "$9\\pi$", "$27\\pi$", "$6\\pi$"]'::jsonb, 0, '$V = 2\pi \int_{0}^{3} x \cdot x \, dx = 2\pi \int_{0}^{3} x^{2} \, dx$. An antiderivative is $F(x) = \dfrac{x^{3}}{3}$, so $V = 2\pi \left[F(3)-F(0)\right] = 2\pi \left[9 - 0\right] = 18\pi$.', 'The Shell Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the volume of the solid formed by revolving about the y-axis the region under $y = x^3$ from x=0 to x=1.', '["$2\\pi/5$", "$\\pi/4$", "$\\pi/3$", "$2\\pi/3$"]'::jsonb, 0, '$V = 2\pi \int_{0}^{1} x \cdot x^{3} \, dx = 2\pi \int_{0}^{1} x^{4} \, dx$. An antiderivative is $F(x) = \dfrac{x^{5}}{5}$, so $V = 2\pi \left[F(1)-F(0)\right] = 2\pi \left[\dfrac{1}{5} - 0\right] = \dfrac{2\pi}{5}$.', 'The Shell Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the volume of the solid formed by revolving about the y-axis the region under $y = \sqrt{x}$ from x=0 to x=4.', '["$128\\pi/5$", "$16\\pi$", "$64\\pi/3$", "$8\\pi$"]'::jsonb, 0, '$V = 2\pi \int_{0}^{4} x \cdot \sqrt{x} \, dx = 2\pi \int_{0}^{4} x^{3/2} \, dx$. An antiderivative is $F(x) = \dfrac{2}{5}x^{5/2}$, so $V = 2\pi \left[F(4)-F(0)\right] = 2\pi \left[\dfrac{2}{5}(32) - 0\right] = 2\pi \cdot \dfrac{64}{5} = \dfrac{128\pi}{5}$.', 'The Shell Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If 1/[(x-1)(x+1)] = A/(x-1) + B/(x+1) for all admissible x, find A.', '["$1/2$", "$-1/2$", "$1$", "$-1$"]'::jsonb, 0, 'Clearing denominators: $1 = A(x+1) + B(x-1)$. Setting $x=1$: $1 = A(2) + B(0) \Rightarrow A = \dfrac{1}{2}$.', 'Method of Partial Fractions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If 1/[(x-1)(x+1)] = A/(x-1) + B/(x+1) for all admissible x, find B.', '["$-1/2$", "$1/2$", "$1$", "$-1$"]'::jsonb, 0, 'Clearing denominators: $1 = A(x+1) + B(x-1)$. Setting $x=-1$: $1 = A(0) + B(-2) \Rightarrow B = -\dfrac{1}{2}$.', 'Method of Partial Fractions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If 5/[(x-2)(x+3)] = A/(x-2) + B/(x+3) for all admissible x, find A and B.', '["$A = 1, B = -1$", "$A = 5, B = -5$", "$A = -1, B = 1$", "$A = 1, B = 1$"]'::jsonb, 0, 'Clearing denominators: $5 = A(x+3) + B(x-2)$. Setting $x=2$: $5 = A(5) \Rightarrow A=1$. Setting $x=-3$: $5 = B(-5) \Rightarrow B=-1$.', 'Method of Partial Fractions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If (3x+1)/[(x-1)(x+2)] = A/(x-1) + B/(x+2) for all admissible x, find A.', '["$4/3$", "$5/3$", "$3$", "$1$"]'::jsonb, 0, 'Clearing denominators: $3x+1 = A(x+2) + B(x-1)$. Setting $x=1$: $3(1)+1 = A(3) \Rightarrow 4 = 3A \Rightarrow A = \dfrac{4}{3}$.', 'Method of Partial Fractions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If 1/[x(x-1)^2] = A/x + B/(x-1) + C/(x-1)^2 for all admissible x, find C (the coefficient of the repeated-factor term 1/(x-1)^2).', '["$1$", "$-1$", "$2$", "$0$"]'::jsonb, 0, 'Clearing denominators: $1 = A(x-1)^{2} + Bx(x-1) + Cx$. Setting $x=1$ eliminates the $A$ and $B$ terms: $1 = A(0) + B(0) + C(1) \Rightarrow C = 1$.', 'Method of Partial Fractions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If the graph of $f(x) = x^2$ is shifted 3 units to the right and 2 units up, the resulting function is $g(x) = ?$', '["$(x-3)^2 + 2$", "$(x+3)^2 + 2$", "$(x-3)^2 - 2$", "$x^2 - 3x + 2$"]'::jsonb, 0, 'Shifting a graph $c$ units to the right replaces $x$ with $x-c$ inside the function, and shifting it $d$ units up adds $d$ to the whole function. So $f(x) = x^{2}$ shifted 3 right and 2 up becomes $g(x) = (x-3)^{2} + 2$.', 'Transformations of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If the graph of $f(x) = \sqrt{x}$ is reflected about the x-axis and shifted 1 unit down, the resulting function is $g(x) = ?$', '["$-\\sqrt{x} - 1$", "$\\sqrt{-x} - 1$", "$\\sqrt{x} - 1$", "$-\\sqrt{x} + 1$"]'::jsonb, 0, 'Reflecting about the x-axis multiplies the function by $-1$, giving $-\sqrt{x}$. Shifting 1 unit down then subtracts 1: $g(x) = -\sqrt{x} - 1$.', 'Transformations of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The graph of $y = f(x)$ is stretched vertically by a factor of 3 and shifted 2 units to the left. Which formula describes the new graph in terms of f?', '["$y = 3f(x+2)$", "$y = 3f(x-2)$", "$y = f(3x+2)$", "$y = f(3x)+2$"]'::jsonb, 0, 'A vertical stretch by factor $3$ multiplies the output: $3f(x)$. Shifting the graph 2 units to the left replaces $x$ with $x+2$ inside: $y = 3f(x+2)$.', 'Transformations of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The graph of $y = x^2$ is shifted 4 units to the right and 8 units down to form $y = (x-4)^2 - 8$. What is the lowest point (vertex) of the new graph?', '["$(4, -8)$", "$(-4, 8)$", "$(4, 8)$", "$(-4, -8)$"]'::jsonb, 0, 'The vertex of $y=x^{2}$ is at the origin $(0,0)$. Shifting 4 units right moves the x-coordinate to $4$, and shifting 8 units down moves the y-coordinate to $-8$, giving the new vertex $(4,-8)$.', 'Transformations of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'To obtain the graph of $y = (2x)^3$ from the graph of $y = x^3$, you should:', '["compress the graph of $y = x^3$ horizontally by a factor of 2", "stretch the graph of $y = x^3$ horizontally by a factor of 2", "shift the graph of $y = x^3$ to the right by 2 units", "stretch the graph of $y = x^3$ vertically by a factor of 2"]'::jsonb, 0, 'Replacing $x$ with $cx$ (for $c>1$) inside a function compresses its graph horizontally by a factor of $c$. Here $y=(2x)^{3}$ replaces $x$ with $2x$, so the graph of $y=x^{3}$ is compressed horizontally by a factor of $2$.', 'Transformations of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'A radioactive substance has a half-life of 30 years. If 100 mg is present initially, approximately how much remains after 100 years?', '["about 9.92 mg", "about 33.3 mg", "about 50 mg", "about 0.99 mg"]'::jsonb, 0, 'With half-life 30 years, the decay model is $y(t) = 100 \cdot 2^{-t/30}$ (equivalently $y(t)=100e^{kt}$ with $k = -\dfrac{\ln 2}{30}$, since $y(30)=\dfrac{100}{2}$ fixes $k$). At $t=100$: $y(100) = 100 \cdot 2^{-100/30} \approx 9.92$ mg.', 'Exponential Growth and Decay', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'A population grows exponentially and doubles every 3 hours. If it starts at 100, how many are there after 9 hours?', '["$800$", "$300$", "$900$", "$600$"]'::jsonb, 0, 'Doubling every 3 hours means after $9$ hours there have been $\dfrac{9}{3}=3$ doubling periods. Starting from $100$: $100 \cdot 2^{3} = 100 \cdot 8 = 800$.', 'Exponential Growth and Decay', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'A quantity grows according to y(t) = y0 * e^(kt). If the quantity triples in 2 years, find k (in terms of ln, per year).', '["$k = \\ln(3)/2$", "$k = \\ln(2)/3$", "$k = 3 \\ln(2)$", "$k = \\ln(3/2)$"]'::jsonb, 0, '$y(2) = y_0 e^{2k} = 3y_0$, so $e^{2k}=3$. Taking the natural log of both sides: $2k = \ln 3$, so $k = \dfrac{\ln 3}{2}$.', 'Exponential Growth and Decay', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If a radioactive substance decays according to y(t) = y0 * e^(-kt), and $k = \frac{\ln 2}{30}$ per year, what is its half-life?', '["30 years", "15 years", "60 years", "0.023 years"]'::jsonb, 0, 'The half-life is the time $T$ for which $y(T) = \dfrac{y_0}{2}$, i.e. $e^{-kT} = \dfrac{1}{2}$, so $kT = \ln 2$, giving $T = \dfrac{\ln 2}{k}$. With $k = \dfrac{\ln 2}{30}$: $T = \dfrac{\ln 2}{\ln 2 / 30} = 30$ years.', 'Exponential Growth and Decay', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Bacteria in a culture grow exponentially. If the population is 200 at t=0 and 800 at t=2 (hours), find the growth constant k in y(t) = 200 e^(kt).', '["$k = \\ln(4)/2$", "$k = \\ln(2)/2$", "$k = \\ln(4)$", "$k = 4/2$"]'::jsonb, 0, '$y(2) = 200 e^{2k} = 800$, so $e^{2k} = 4$. Taking the natural log: $2k = \ln 4$, so $k = \dfrac{\ln 4}{2}$.', 'Exponential Growth and Decay', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = \sqrt{x}$ and $g(x) = x - 4$, what is the domain of (f+g)(x)?', '["$x >= 0$", "$x >= 4$", "all real numbers", "$x > 0$"]'::jsonb, 0, 'The domain of $f+g$ is the intersection of the domains of $f$ and $g$. $f(x) = \sqrt{x}$ requires $x \geq 0$, while $g(x) = x - 4$ is defined for all real $x$. The intersection is $x \geq 0$.', 'Domain of Combined and Composite Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = 1/(x-2)$ and $g(x) = \sqrt{x}$, what is the domain of (f/g)(x)?', '["$x > 0$ and x not equal to 2", "$x >= 0$", "x not equal to 2", "$x > 2$"]'::jsonb, 0, '$(f/g)(x)$ requires $g(x) \neq 0$ in addition to both $f$ and $g$ being defined. $f$ requires $x \neq 2$; $g(x)=\sqrt{x}$ requires $x \geq 0$ and, to avoid dividing by $g(x)=0$, also $x \neq 0$. Combining these: $x > 0$ and $x \neq 2$.', 'Domain of Combined and Composite Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = \sqrt{x-1}$ and $g(x) = \sqrt{3-x}$, what is the domain of (f+g)(x)?', '["$1 <= x <= 3$", "$x >= 1$", "$x <= 3$", "all real numbers"]'::jsonb, 0, '$f(x) = \sqrt{x-1}$ requires $x-1 \geq 0$, i.e. $x \geq 1$. $g(x) = \sqrt{3-x}$ requires $3-x \geq 0$, i.e. $x \leq 3$. The domain of the sum is the intersection of both: $1 \leq x \leq 3$.', 'Domain of Combined and Composite Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = x^2$ and $g(x) = \sqrt{x-1}$, what is the domain of (f o g)(x), the composition f(g(x))?', '["$x >= 1$", "all real numbers", "$x > 1$", "$x >= 0$"]'::jsonb, 0, 'For $(f \circ g)(x) = f(g(x))$ to be defined, $x$ must first be in the domain of $g$: $g(x) = \sqrt{x-1}$ requires $x \geq 1$. Since $f(x)=x^{2}$ accepts any real input, no further restriction is added, so the domain of $f \circ g$ is $x \geq 1$.', 'Domain of Combined and Composite Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If $f(x) = \sqrt{x}$ and $g(x) = x - 4$, what is the domain of (g o f)(x), the composition g(f(x))?', '["$x >= 0$", "$x >= 4$", "all real numbers", "$x > 4$"]'::jsonb, 0, 'For $(g \circ f)(x) = g(f(x))$, $x$ must first be in the domain of $f$: $f(x) = \sqrt{x}$ requires $x \geq 0$. Since $g(x)=x-4$ accepts any real input, no further restriction is added, so the domain of $g \circ f$ is $x \geq 0$.', 'Domain of Combined and Composite Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^2 - 4x + 3$, find the value of c in (1,3) where f''(c) = 0.', '["$c = 2$", "$c = 1.5$", "$c = 2.5$", "$c = 3$"]'::jsonb, 0, '$f''(x) = 2x - 4$. Setting $f''(c) = 0$: $2c - 4 = 0 \Rightarrow c = 2$, which indeed lies in $(1,3)$, confirming Rolle''s Theorem.', 'Rolle''s Theorem and the Mean Value Theorem', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^3 - 3x$, find the value of c in (0,2) satisfying f''(c) = [$f(2)$ $-$ $f(0)$$]/2$.', '["$c = 2/\\sqrt{3}$", "$c = 1$", "$c = \\sqrt{3}$", "$c = 2/3$"]'::jsonb, 0, '$\dfrac{f(2)-f(0)}{2} = \dfrac{2 - 0}{2} = 1$. Setting $f''(c) = 3c^{2} - 3 = 1$ gives $c^{2} = \dfrac{4}{3}$, so $c = \dfrac{2}{\sqrt{3}}$ (taking the positive root, since it must lie in $(0,2)$).', 'Rolle''s Theorem and the Mean Value Theorem', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Rolle''s Theorem requires a function f to be continuous on [a,b], differentiable on (a,b), and f(a) = f(b). Under these conditions, the theorem guarantees:', '["at least one point c in (a,b) where f''(c) = 0", "that f is a constant function on [a,b]", "that f has no critical points anywhere on [a,b]", "that f(a) and f(b) must both equal zero"]'::jsonb, 0, 'Rolle''s Theorem states that if $f(a) = f(b)$ and $f$ is continuous on $[a,b]$ and differentiable on $(a,b)$, then there exists at least one $c \in (a,b)$ with $f''(c) = 0$ -- the tangent is horizontal somewhere between the two equal-height points.', 'Rolle''s Theorem and the Mean Value Theorem', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^2$, find the value of c in (1,4) satisfying f''(c) = [$f(4)$ $-$ $f(1)$$]/(4 - 1)$.', '["$c = 5/2$", "$c = 2$", "$c = 3$", "$c = 5/4$"]'::jsonb, 0, '$\dfrac{f(4)-f(1)}{4-1} = \dfrac{16-1}{3} = 5$. Setting $f''(c) = 2c = 5$ gives $c = \dfrac{5}{2}$, which lies in $(1,4)$.', 'Rolle''s Theorem and the Mean Value Theorem', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The Mean Value Theorem states that for f continuous on [a,b] and differentiable on (a,b), there exists c in (a,b) such that f''(c) equals:', '["the average (mean) rate of change of f over [a,b], i.e. $[f(b) - f(a)]/(b - a)$", "the value of f at the midpoint of [a,b]", "zero, regardless of the function", "the sum of f(a) and f(b) divided by two"]'::jsonb, 0, 'The Mean Value Theorem guarantees a point $c$ where the instantaneous rate of change $f''(c)$ equals the average rate of change over the whole interval, $\dfrac{f(b)-f(a)}{b-a}$ -- geometrically, the tangent at $c$ is parallel to the secant line through $(a,f(a))$ and $(b,f(b))$.', 'Rolle''s Theorem and the Mean Value Theorem', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If x = t^2 - 1 and $y = t^2 + t$, find dy/dx in terms of t.', '["$(2t+1)/(2t)$", "$(2t)/(2t+1)$", "$2t+1$", "$t+1$"]'::jsonb, 0, '$\dfrac{dx}{dt} = 2t$ and $\dfrac{dy}{dt} = 2t+1$. So $\dfrac{dy}{dx} = \dfrac{dy/dt}{dx/dt} = \dfrac{2t+1}{2t}$.', 'Derivatives of Functions Expressed Parametrically', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If x = cos(t) and $y = \sin(t)$, find dy/dx in terms of t.', '["$-\\cot(t)$", "$\\cot(t)$", "$-\\tan(t)$", "$\\tan(t)$"]'::jsonb, 0, '$\dfrac{dx}{dt} = -\sin(t)$ and $\dfrac{dy}{dt} = \cos(t)$. So $\dfrac{dy}{dx} = \dfrac{\cos(t)}{-\sin(t)} = -\cot(t)$.', 'Derivatives of Functions Expressed Parametrically', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If x = 2t and $y = t^2$, find dy/dx at t = 1.', '["$1$", "$2$", "$1/2$", "$4$"]'::jsonb, 0, '$\dfrac{dx}{dt} = 2$ and $\dfrac{dy}{dt} = 2t$, so $\dfrac{dy}{dx} = \dfrac{2t}{2} = t$. At $t=1$: $\dfrac{dy}{dx} = 1$.', 'Derivatives of Functions Expressed Parametrically', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If x = t^3 and $y = t^2$, find dy/dx in terms of t.', '["$2/(3t)$", "$3t/2$", "$2t/3$", "$3/(2t)$"]'::jsonb, 0, '$\dfrac{dx}{dt} = 3t^{2}$ and $\dfrac{dy}{dt} = 2t$, so $\dfrac{dy}{dx} = \dfrac{2t}{3t^{2}} = \dfrac{2}{3t}$.', 'Derivatives of Functions Expressed Parametrically', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If x and y are both given as functions of a parameter t, the chain-rule formula for dy/dx in terms of t is:', '["$dy/dx = (dy/dt) / (dx/dt)$, provided dx/dt is not zero", "$dy/dx = (dy/dt) times (dx/dt)$", "$dy/dx = dy/dt$, regardless of x", "$dy/dx = (dx/dt) / (dy/dt)$"]'::jsonb, 0, 'By the chain rule, $\dfrac{dy}{dt} = \dfrac{dy}{dx} \cdot \dfrac{dx}{dt}$, so solving for $\dfrac{dy}{dx}$ gives $\dfrac{dy}{dx} = \dfrac{dy/dt}{dx/dt}$, valid wherever $\dfrac{dx}{dt} \neq 0$.', 'Derivatives of Functions Expressed Parametrically', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $y = log_2(x) (log base 2 of x)$, for $x > 0.$', '["$1/(x \\ln(2))$", "$1/x$", "$\\ln(2)/x$", "$1/(2x)$"]'::jsonb, 0, 'Using the change-of-base identity $\log_2(x) = \dfrac{\ln x}{\ln 2}$: $\dfrac{d}{dx}\left[\dfrac{\ln x}{\ln 2}\right] = \dfrac{1}{\ln 2} \cdot \dfrac{1}{x} = \dfrac{1}{x \ln 2}$.', 'Logarithms and Exponentials to Other Bases', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $y = 3^x$.', '["$3^x \\ln(3)$", "$3^x$", "$x 3^{x-1}$", "$3^x / \\ln(3)$"]'::jsonb, 0, 'For $y = b^{x}$ with constant base $b$, $\dfrac{d}{dx}[b^{x}] = b^{x} \ln b$. With $b=3$: $\dfrac{d}{dx}[3^{x}] = 3^{x} \ln 3$.', 'Logarithms and Exponentials to Other Bases', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $y = log_10(x) ($the common logarithm), for $x > 0.$', '["$1/(x \\ln(10))$", "$1/x$", "$\\ln(10)/x$", "$10/x$"]'::jsonb, 0, '$\log_{10}(x) = \dfrac{\ln x}{\ln 10}$, so $\dfrac{d}{dx}[\log_{10}(x)] = \dfrac{1}{\ln 10} \cdot \dfrac{1}{x} = \dfrac{1}{x \ln 10}$.', 'Logarithms and Exponentials to Other Bases', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate log_2(8) (log base 2 of 8).', '["$3$", "$4$", "$8$", "$2$"]'::jsonb, 0, '$\log_2(8)$ asks: to what power must 2 be raised to get 8? Since $2^{3} = 8$, $\log_2(8) = 3$.', 'Logarithms and Exponentials to Other Bases', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The change-of-base formula expresses log_b(x) (log base b of x) in terms of natural logarithms as:', '["$log_b(x) = \\ln(x) / \\ln(b)$", "log_b(x) = ln(x) times ln(b)", "$log_b(x) = \\ln(b) / \\ln(x)$", "$log_b(x) = \\ln(x) + \\ln(b)$"]'::jsonb, 0, 'The change-of-base formula is $\log_b(x) = \dfrac{\ln x}{\ln b}$, which lets any logarithm be computed or differentiated using natural logarithms.', 'Logarithms and Exponentials to Other Bases', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The hyperbolic sine function, sinh(x), is defined in terms of the exponential function as:', '["sinh(x) = (e^x - e^(-x))/2", "sinh(x) = (e^x + e^(-x))/2", "sinh(x) = e^x - e^(-x)", "sinh(x) = (e^x - e^(-x))/x"]'::jsonb, 0, 'By definition, $\sinh(x) = \dfrac{e^{x} - e^{-x}}{2}$, the ''odd part'' of the exponential function.', 'Hyperbolic Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $y = sinh(x)$.', '["cosh(x)", "sinh(x)", "-cosh(x)", "tanh(x)"]'::jsonb, 0, 'Since $\sinh(x) = \dfrac{e^{x}-e^{-x}}{2}$, differentiating gives $\dfrac{d}{dx}[\sinh(x)] = \dfrac{e^{x}+e^{-x}}{2} = \cosh(x)$.', 'Hyperbolic Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $y = cosh(x)$.', '["sinh(x)", "cosh(x)", "-sinh(x)", "1/cosh(x)"]'::jsonb, 0, 'Since $\cosh(x) = \dfrac{e^{x}+e^{-x}}{2}$, differentiating gives $\dfrac{d}{dx}[\cosh(x)] = \dfrac{e^{x}-e^{-x}}{2} = \sinh(x)$.', 'Hyperbolic Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The fundamental hyperbolic identity relating cosh(x) and sinh(x) is:', '["cosh^2(x) - sinh^2(x) = 1", "cosh^2(x) + sinh^2(x) = 1", "cosh(x) - sinh(x) = 1", "cosh^2(x) - sinh^2(x) = 0"]'::jsonb, 0, 'Substituting the exponential definitions and expanding confirms $\cosh^{2}(x) - \sinh^{2}(x) = 1$ for all $x$ -- the hyperbolic analogue of $\cos^{2}\theta + \sin^{2}\theta = 1$.', 'Hyperbolic Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate cosh(0).', '["$1$", "$0$", "$-1$", "e"]'::jsonb, 0, '$\cosh(0) = \dfrac{e^{0}+e^{-0}}{2} = \dfrac{1+1}{2} = 1$.', 'Hyperbolic Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $y = tanh(x)$, given tanh(x) = sinh(x)/cosh(x).', '["1 - tanh^2(x)", "1 + tanh^2(x)", "sech^2(x) only, never in terms of tanh", "cosh(x)/sinh(x)"]'::jsonb, 0, 'Using the quotient rule on $\tanh(x) = \dfrac{\sinh(x)}{\cosh(x)}$: $\tanh''(x) = \dfrac{\cosh^{2}(x) - \sinh^{2}(x)}{\cosh^{2}(x)} = \dfrac{1}{\cosh^{2}(x)}$, which (using $\cosh^{2}(x) = 1 + \sinh^{2}(x) = \dfrac{1}{1-\tanh^{2}(x)}$) simplifies to $1 - \tanh^{2}(x)$.', 'Hyperbolic Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The tangent line to $y = \sqrt{x}$ at x = 4 is used to estimate sqrt(4.1). What estimate does it give?', '["$2.025$", "$2.05$", "$2.1$", "$2.0$"]'::jsonb, 0, '$f(x)=\sqrt{x}$, $f''(x) = \dfrac{1}{2\sqrt{x}}$. At $a=4$: $f(4)=2$, $f''(4) = \dfrac{1}{4}$. So $L(4.1) = 2 + \dfrac{1}{4}(0.1) = 2 + 0.025 = 2.025$.', 'Linear Approximation and Differentials', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The differential dy of a function $y = f(x)$ is defined as:', '["$dy = f''(x) dx$, the linear approximation of the change in y for a small change dx in x", "$dy = f(x) dx$, the product of the function and dx", "$dy = f''''(x) dx$, using the second derivative", "dy is always equal to the actual change in y, exactly"]'::jsonb, 0, 'The differential is defined as $dy = f''(x)\,dx$ -- it approximates (but is not exactly equal to) the true change $\Delta y = f(x+dx) - f(x)$ for small $dx$, using the tangent line''s slope.', 'Linear Approximation and Differentials', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For $f(x) = x^2$, find the differential dy at x = 3 when dx = 0.01.', '["$0.06$", "$0.03$", "$0.09$", "$0.01$"]'::jsonb, 0, '$dy = f''(x)\,dx = 2x\,dx$. At $x=3$, $dx=0.01$: $dy = 2(3)(0.01) = 0.06$.', 'Linear Approximation and Differentials', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The tangent line to $y = x^3$ at x = 2 is used to estimate (1.99)^3. What estimate does it give?', '["$7.88$", "$8.00$", "$7.94$", "$7.76$"]'::jsonb, 0, '$f''(x) = 3x^{2}$, so $f''(2) = 12$. With $\Delta x = -0.01$: $L(1.99) = f(2) + f''(2)(-0.01) = 8 - 0.12 = 7.88$.', 'Linear Approximation and Differentials', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Linear approximation near x = a uses which line to estimate f(x) for x close to a?', '["the tangent line to the graph of f at x = a", "the secant line joining the endpoints of the domain of f", "the x-axis itself, regardless of f", "a vertical line through x = a"]'::jsonb, 0, 'Linear approximation replaces the curve $y=f(x)$, near $x=a$, with its tangent line at $x=a$: $L(x) = f(a) + f''(a)(x-a)$, which closely matches $f(x)$ for $x$ near $a$.', 'Linear Approximation and Differentials', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The arc length formula for a smooth curve $y = f(x)$ from x = a to x = b is:', '["L = integral from a to b of sqrt(1 + [f''(x)]^2) dx", "L = integral from a to b of f(x) dx", "L = integral from a to b of f''(x) dx", "L = integral from a to b of [f(x)]^2 dx"]'::jsonb, 0, 'The arc length of $y=f(x)$ from $x=a$ to $x=b$ is $L = \int_{a}^{b} \sqrt{1+[f''(x)]^{2}} \, dx$, derived from summing tiny hypotenuse lengths $\sqrt{(dx)^2+(dy)^2}$ along the curve.', 'Lengths of Curves', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the arc length of the line $y = (2/3)x$ from x = 0 to x = 3.', '["$\\sqrt{13}$", "$3$", "$5$", "$13$"]'::jsonb, 0, '$f''(x) = \dfrac{2}{3}$, so $L = \int_{0}^{3} \sqrt{1+\dfrac{4}{9}} \, dx = \sqrt{\dfrac{13}{9}} \cdot 3 = \sqrt{13}$.', 'Lengths of Curves', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the arc length of the line $y = x$ from x = 0 to x = 4.', '["$4 \\sqrt{2}$", "$4$", "$8$", "$16$"]'::jsonb, 0, '$f''(x) = 1$, so $L = \int_{0}^{4} \sqrt{1+1} \, dx = \sqrt{2} \int_{0}^{4} dx = 4\sqrt{2}$.', 'Lengths of Curves', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For the arc length formula L = integral of sqrt(1 + [f''(x)]^2) dx, the term [f''(x)]^2 arises from:', '["squaring the slope of the curve, representing (dy/dx)^2 in the Pythagorean length element", "the second derivative of f", "the average value of f over the interval", "the area under the curve"]'::jsonb, 0, 'Each infinitesimal arc segment has length $ds = \sqrt{(dx)^2+(dy)^2} = \sqrt{1+(dy/dx)^2}\,dx$, so $[f''(x)]^2 = (dy/dx)^2$ comes directly from the Pythagorean theorem applied to a tiny piece of the curve.', 'Lengths of Curves', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'A Riemann sum approximates the area under a curve $y = f(x)$ on [a,b] by:', '["summing the areas of thin rectangles whose heights are sample values of f", "averaging only the two endpoint values f(a) and f(b)", "computing the slope of the line joining (a,f(a)) and (b,f(b))", "finding the single maximum value of f on the interval"]'::jsonb, 0, 'A Riemann sum divides $[a,b]$ into subintervals, forms a rectangle on each with height given by a sample value of $f$ within that subinterval, and adds up the rectangles'' areas to approximate the total area under the curve.', 'Areas and Riemann Sums', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'As the number of rectangles in a Riemann sum approaches infinity (and each rectangle''s width approaches zero), the Riemann sum approaches:', '["the definite integral of f over the interval", "the derivative of f at the interval''s midpoint", "a value that always equals zero", "the maximum possible area, regardless of f"]'::jsonb, 0, 'This is the definition of the definite integral: $\int_a^b f(x)\,dx = \lim_{n \to \infty} \sum_{i=1}^{n} f(x_i^{*}) \Delta x$, the limit of Riemann sums as the rectangles become infinitely thin.', 'Areas and Riemann Sums', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Estimate the area under $y = x^2$ on [0,2] using 4 rectangles of equal width, taking the height of each from the right endpoint of its subinterval.', '["$15/4$", "$8/3$", "$4$", "$10/4$"]'::jsonb, 0, 'With $n=4$ rectangles on $[0,2]$, each has width $\Delta x = \dfrac{1}{2}$, and right endpoints $x_k = \dfrac{k}{2}$ for $k=1,2,3,4$. The sum is $\sum_{k=1}^{4} \left(\dfrac{k}{2}\right)^{2} \cdot \dfrac{1}{2} = \dfrac{1}{8}(1+4+9+16) = \dfrac{30}{8} = \dfrac{15}{4}$.', 'Areas and Riemann Sums', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'The exact area under $y = x^2$ on [0,2], found by evaluating the definite integral directly, is:', '["$8/3$", "$4$", "$15/4$", "$2$"]'::jsonb, 0, '$\int_{0}^{2} x^{2} \, dx = \left[\dfrac{x^{3}}{3}\right]_{0}^{2} = \dfrac{8}{3} - 0 = \dfrac{8}{3}$. This is the exact value that a Riemann sum with more and more rectangles converges toward.', 'Areas and Riemann Sums', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = x^2 + 3$, $g(x) = 2x - 1$, find (f o g)(2).', '["$12$", "$9$", "$7$", "$15$"]'::jsonb, 0, '$(f \circ g)(2) = f(g(2))$. First $g(2) = 2(2)-1 = 3$. Then $f(3) = 3^{2}+3 = 12$.', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = \sqrt{x + 1}$, $g(x) = x^2 - 1$, find (f o g)(3).', '["$3$", "$4$", "$\\sqrt{10}$", "$2$"]'::jsonb, 0, '$g(3) = 3^{2} - 1 = 8$. Then $f(8) = \sqrt{8+1} = \sqrt{9} = 3$.', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = 3x - 2$, $g(x) = x^2 + x$, find (f o g)(1).', '["$4$", "$1$", "$7$", "$-2$"]'::jsonb, 0, '$g(1) = 1^{2}+1 = 2$. Then $f(2) = 3(2)-2 = 4$.', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Given $f(x) = x^2 - x$, $g(x) = 4 - x$, find (f o g)(2).', '["$2$", "$0$", "$4$", "$6$"]'::jsonb, 0, '$g(2) = 4-2 = 2$. Then $f(2) = 2^{2}-2 = 2$.', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = (3x - 1)^5$.', '["$15(3x-1)^4$", "$5(3x-1)^4$", "$15(3x-1)^5$", "$3(3x-1)^4$"]'::jsonb, 0, 'Chain Rule: with $u = 3x-1$, $\dfrac{d}{dx}[u^{5}] = 5u^{4} \cdot u''$. Here $u''=3$, so $f''(x) = 5(3x-1)^{4} \cdot 3 = 15(3x-1)^{4}$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \sqrt{4x + 1}$.', '["$2/\\sqrt{4x+1}$", "$4/\\sqrt{4x+1}$", "$1/\\sqrt{4x+1}$", "$2 \\sqrt{4x+1}$"]'::jsonb, 0, 'Writing $f(x) = (4x+1)^{1/2}$, the Chain Rule gives $f''(x) = \dfrac{1}{2}(4x+1)^{-1/2} \cdot 4 = \dfrac{2}{\sqrt{4x+1}}$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = \cos(x^2 - 1)$.', '["$-2x \\sin(x^2 - 1)$", "$2x \\sin(x^2 - 1)$", "$-\\sin(x^2-1)$", "$-2x \\cos(x^2-1)$"]'::jsonb, 0, 'Chain Rule: with $u = x^{2}-1$, $\dfrac{d}{dx}[\cos(u)] = -\sin(u) \cdot u''$. Here $u'' = 2x$, so $f''(x) = -2x\sin(x^{2}-1)$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = 1/(2x + 3)^2$.', '["$-4/(2x+3)^3$", "$4/(2x+3)^3$", "$-2/(2x+3)^3$", "$-4/(2x+3)^2$"]'::jsonb, 0, 'Writing $f(x) = (2x+3)^{-2}$, the Chain Rule gives $f''(x) = -2(2x+3)^{-3} \cdot 2 = \dfrac{-4}{(2x+3)^{3}}$.', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = (x + 1)(x - 3)$.', '["$2x - 2$", "$2x + 2$", "$x - 2$", "$2x - 3$"]'::jsonb, 0, 'Product Rule: $(uv)'' = u''v+uv''$. With $u=x+1$, $v=x-3$: $u''=1$, $v''=1$. $f''(x) = (1)(x-3)+(x+1)(1) = (x-3)+(x+1) = 2x-2$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = (2x + 1)/(x - 1)$.', '["$-3/(x-1)^2$", "$3/(x-1)^2$", "$2/(x-1)^2$", "$-2/(x-1)^2$"]'::jsonb, 0, 'Quotient Rule: $u=2x+1$, $v=x-1$, $u''=2$, $v''=1$. $f''(x) = \dfrac{u''v-uv''}{v^2} = \dfrac{2(x-1)-(2x+1)(1)}{(x-1)^2} = \dfrac{2x-2-2x-1}{(x-1)^2} = \dfrac{-3}{(x-1)^2}$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = x^3 \cos(x)$.', '["$3x^2 \\cos(x) - x^3 \\sin(x)$", "$3x^2 \\cos(x) + x^3 \\sin(x)$", "$-x^3 \\sin(x)$", "$3x^2 \\sin(x)$"]'::jsonb, 0, 'Product Rule: $u=x^{3}$, $v=\cos(x)$, $u''=3x^{2}$, $v''=-\sin(x)$. $f''(x) = 3x^{2}\cos(x) + x^{3}(-\sin(x)) = 3x^{2}\cos(x) - x^{3}\sin(x)$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of $f(x) = x^2/(x + 2)$.', '["$(x^2 + 4x)/(x+2)^2$", "$2x/(x+2)^2$", "$(x^2 - 4x)/(x+2)^2$", "$1/(x+2)^2$"]'::jsonb, 0, 'Quotient Rule: $u=x^{2}$, $v=x+2$, $u''=2x$, $v''=1$. $f''(x) = \dfrac{2x(x+2) - x^{2}(1)}{(x+2)^{2}} = \dfrac{2x^{2}+4x-x^{2}}{(x+2)^{2}} = \dfrac{x^{2}+4x}{(x+2)^{2}}$.', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the integral of x(x^2 + 1)^3 dx.', '["$(x^2+1)^4/8 + C$", "$(x^2+1)^4/4 + C$", "$4x(x^2+1)^4 + C$", "$(x^2+1)^3/6 + C$"]'::jsonb, 0, 'Let $u = x^{2}+1$, so $du = 2x\,dx$. Then $\int x(x^{2}+1)^{3}\,dx = \dfrac{1}{2}\int u^{3}\,du = \dfrac{1}{2}\cdot\dfrac{u^{4}}{4}+C = \dfrac{(x^{2}+1)^{4}}{8}+C$.', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the integral of sin(x) cos^2(x) dx.', '["$-cos^3(x)/3 + C$", "$cos^3(x)/3 + C$", "$-sin^3(x)/3 + C$", "$-cos^3(x) + C$"]'::jsonb, 0, 'Let $u=\cos(x)$, so $du = -\sin(x)\,dx$. Then $\int \sin(x)\cos^{2}(x)\,dx = -\int u^{2}\,du = -\dfrac{u^{3}}{3}+C = -\dfrac{\cos^{3}(x)}{3}+C$.', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the integral of x^2/(x^3 + 1) dx.', '["$(1/3) ln|x^3+1| + C$", "$ln|x^3+1| + C$", "$(1/3)(x^3+1) + C$", "$3 ln|x^3+1| + C$"]'::jsonb, 0, 'Let $u = x^{3}+1$, so $du = 3x^{2}\,dx$. Then $\int \dfrac{x^{2}}{x^{3}+1}\,dx = \dfrac{1}{3}\int \dfrac{du}{u} = \dfrac{1}{3}\ln|u|+C = \dfrac{1}{3}\ln|x^{3}+1|+C$.', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 4} [(x^2 - 16)/(x - 4)]$.', '["$8$", "$0$", "$4$", "$16$"]'::jsonb, 0, 'Direct substitution gives $\dfrac{0}{0}$, so factor: $\dfrac{x^{2}-16}{x-4} = \dfrac{(x-4)(x+4)}{x-4} = x+4$ for $x \neq 4$. So $\lim_{x \to 4}(x+4) = 8$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to 3} [(x^3 - 27)/(x - 3)]$.', '["$27$", "$9$", "$3$", "$0$"]'::jsonb, 0, 'Factoring the difference of cubes: $x^{3}-27 = (x-3)(x^{2}+3x+9)$, so $\dfrac{x^{3}-27}{x-3} = x^{2}+3x+9$ for $x\neq3$. At $x=3$: $9+9+9 = 27$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate $\lim_{x \to -2} [4x^2 - 3x + 1]$.', '["$23$", "$17$", "$-23$", "$9$"]'::jsonb, 0, 'This is a polynomial, so it''s continuous everywhere and the limit equals direct substitution: $4(-2)^{2} - 3(-2) + 1 = 16+6+1 = 23$.', 'Limits of Polynomial and Rational Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = 4 - x^2$ and the x-axis, between x=-2 and x=2.', '["$32/3$", "$16$", "$8$", "$32/5$"]'::jsonb, 0, 'Area $= \int_{-2}^{2} (4-x^{2})\,dx$. An antiderivative is $F(x)=4x-\dfrac{x^{3}}{3}$, so Area $= F(2)-F(-2) = \left(8-\dfrac{8}{3}\right)-\left(-8+\dfrac{8}{3}\right) = \dfrac{32}{3}$.', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by $y = x + 2$ and $y = x^2$, between their intersection points x=-1 and x=2.', '["$9/2$", "$3$", "$9$", "$6$"]'::jsonb, 0, 'Since $x+2 \geq x^{2}$ on $[-1,2]$, Area $= \int_{-1}^{2} [(x+2)-x^{2}]\,dx$. An antiderivative is $F(x)=\dfrac{x^{2}}{2}+2x-\dfrac{x^{3}}{3}$, giving $F(2)-F(-1) = \dfrac{16}{3} - \left(-\dfrac{7}{6}\right) = \dfrac{9}{2}$.', 'Areas of Plane Regions', false);
